function refreshReviewFeedbackAssignmentHeartbeat(request = {}, options = {}, context = {}) {
  const owner = request.laneOwner || "";
  if (!request.assignmentId || !owner) {
    return { skipped: true, reason: "assignment-or-owner-missing" };
  }
  const args = [
    "./scripts/codex-workspace.mjs",
    "heartbeat",
    request.assignmentId,
    "--owner",
    owner,
    "--phase",
    "in_progress",
    "--summary",
    "manager review feedback routed; worker applying patch findings",
    "--summary-json",
  ];
  if (options.stateRoot) {
    args.push("--state-root", options.stateRoot);
  }
  const runner = context.runner || spawnSync;
  const result = runner("node", args, { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
  if (result?.error) return { ok: false, error: result.error.message || "heartbeat failed" };
  if ((result?.status ?? 0) !== 0) return { ok: false, error: String(result?.stderr || result?.stdout || "heartbeat failed").trim(), status: result?.status };
  return { ok: true, mutation: "assignment heartbeat metadata only", assignmentId: request.assignmentId, phase: "in_progress" };
}

function updateSprintTimestampLine(source, key, timestamp) {
  return String(source || "").replace(new RegExp(`^(${escapeRegExp(key)}:\\s*).*$`, "m"), `$1${timestamp}`);
}

function replaceStoryMarkdownStatus(source, fromStatus, toStatus) {
  const blockPattern = new RegExp(`(^## Status\\s*\\r?\\n\\s*)${escapeRegExp(fromStatus)}(\\s*)`, "mi");
  const linePattern = new RegExp(`^(Status:\\s*)${escapeRegExp(fromStatus)}(\\s*)$`, "mi");
  if (blockPattern.test(source)) {
    return source.replace(blockPattern, `$1${toStatus}$2`);
  }
  return source.replace(linePattern, `$1${toStatus}$2`);
}

function isDoneSprintStory(assignmentId = "", storyStatuses = {}) {
  const rawId = String(assignmentId || "").trim();
  const storyKey = normalizeBmadStoryAssignmentId(rawId);
  const safeId = sanitizeLedgerField(storyKey || rawId, "", 140);
  if (!rawId || !isPlainObject(storyStatuses)) return false;
  if (String(storyStatuses[rawId] || storyStatuses[storyKey] || storyStatuses[safeId] || "").toLowerCase() === "done") return true;
  return Object.entries(storyStatuses).some(([storyId, status]) =>
    String(status || "").toLowerCase() === "done" &&
    sanitizeLedgerField(storyId, "", 140) === safeId
  );
}

function normalizeBmadStoryAssignmentId(assignmentId = "") {
  const rawId = String(assignmentId || "").trim();
  const withoutPrefix = rawId.startsWith("bmad-") ? rawId.slice("bmad-".length) : rawId;
  return sanitizeLedgerField(withoutPrefix, "", 140);
}

function assignmentRecordFreshEnough(record = {}, nowMs = Date.now(), staleAfterSeconds = 86400) {
  const timestampMs = parseTimeMs(record.last_heartbeat_at || record.lastHeartbeatAt || record.updated_at || record.updatedAt || record.assigned_at || record.assignedAt);
  if (!timestampMs) return false;
  return nowMs - timestampMs <= staleAfterSeconds * 1000;
}

function taskManifestWorktreePath(stateRoot = "", taskId = "") {
  const safeTaskId = sanitizeLedgerField(taskId || "", "", 160);
  if (!stateRoot || !safeTaskId || !/^[a-z0-9._-]+$/i.test(safeTaskId)) return "";
  const root = resolve(stateRoot);
  const manifestPath = resolve(root, "tasks", `${safeTaskId}.json`);
  if (!isInsideOrSame(manifestPath, root) || !existsSync(manifestPath)) return "";
  try {
    const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
    const fromManifest = manifest.worktree_path || manifest.worktreePath || "";
    const fromHandoff = Array.isArray(manifest.dispatch_handoffs) && manifest.dispatch_handoffs.length > 0
      ? manifest.dispatch_handoffs.findLast?.((handoff) => handoff?.worktree_path || handoff?.worktreePath)?.worktree_path ||
        manifest.dispatch_handoffs.findLast?.((handoff) => handoff?.worktree_path || handoff?.worktreePath)?.worktreePath ||
        ""
      : "";
    return sanitizeLedgerField(fromManifest || fromHandoff, "", 260);
  } catch {
    return "";
  }
}

function resolveManagerAdmittedLaneHandoff(lane = {}, paths = {}, context = {}, options = {}) {
  if (!isPlainObject(lane.mutationAdmission)) return { ok: true, lane };
  if (options.apply !== true && lane.mutationAdmission.outcome === "create_managed_lane") {
    return {
      ok: true,
      lane: {
        ...lane,
        worktreePath: sanitizeLedgerField(lane.mutationAdmission.laneEvidence?.worktreePath || lane.worktreePath || "", "", 260),
        workerHandoff: null,
        admissionHandoffPreview: true,
      },
    };
  }
  const handoff = (context.admittedLaneHandoff || handoffAdmittedManagedLane)(lane.mutationAdmission, {
    ...(isPlainObject(context.admittedLaneHandoffContext) ? context.admittedLaneHandoffContext : {}),
    ...(lane.handoffDescription ? { description: lane.handoffDescription } : {}),
    baseCheckoutPath: context.baseCheckoutPath || repoRoot,
  });
  const cwd = sanitizeLedgerField(handoff?.workerHandoff?.cwd || "", "", 260);
  if (handoff?.status !== "ready" || !cwd) {
    return {
      ok: false,
      message: sanitizeLedgerField(handoff?.reasonCode || "managed lane handoff did not return a worker CWD", "managed lane handoff did not return a worker CWD", 180),
      nextAction: sanitizeLedgerField(handoff?.nextSafeAction || "Inspect managed-lane admission evidence before assigning a worker.", "Inspect managed-lane admission evidence before assigning a worker.", 240),
    };
  }
  return {
    ok: true,
    lane: {
      ...lane,
      worktreePath: cwd,
      workerHandoff: { cwd },
      preWriteGuardEvidence: handoff.preWriteGuardEvidence || null,
    },
  };
}

function buildWorkerHandoffPairing(worker = {}, lane = {}, paths = {}) {
  const handoffPath = join(paths.root, "handoffs", `${worker.workerId}-${lane.assignmentId}.md`);
  const pastePath = join(paths.root, "handoffs", `${worker.workerId}-${lane.assignmentId}.paste.txt`);
  return {
    workerId: worker.workerId,
    sessionName: worker.sessionName,
    owner: worker.owner,
    runId: paths.runId,
    stateRoot: paths.proof?.state?.root || "",
    assignmentId: lane.assignmentId,
    taskId: lane.taskId,
    branch: lane.branch,
    laneOwner: lane.laneOwner || "",
    phase: lane.phase || "handoff",
    worktreePath: lane.worktreePath || "",
    workerHandoff: lane.workerHandoff || null,
    preWriteGuardEvidence: lane.preWriteGuardEvidence || null,
    reviewFindingsPath: lane.reviewFindingsPath || "",
    handoffPath,
    pastePath,
    pasteText: `Please read and follow this manager handoff file: ${handoffPath}`,
    retention: "handoff_path_and_summary",
  };
}

function renderWorkerHandoffFile(pairing = {}) {
  const ownerFlag = pairing.laneOwner ? ` --owner ${shellSingleQuote(pairing.laneOwner)}` : "";
  const sourceContextLines = workerHandoffSourceContextLines(pairing);
  const reviewFeedbackInstructions = pairing.reviewFindingsPath
    ? [
      "9. This is a review-feedback handoff. Read the compact delegated review findings path below, apply only required fixes for this lane, rerun focused verification, and checkpoint the result for another delegated review.",
    ]
    : [];
  const checkpointCommand = [
    "node ./scripts/manager-ledger.mjs append-checkpoint --summary-json",
    `--run-id ${shellSingleQuote(pairing.runId)}`,
    ...(pairing.stateRoot ? [`--state-root ${shellSingleQuote(pairing.stateRoot)}`] : []),
    `--worker-id ${shellSingleQuote(pairing.workerId)}`,
    `--summary ${shellSingleQuote("replace with compact progress, verification, or user-facing checkpoint")}`,
    `--authority-basis ${shellSingleQuote("manager-owned-worker-checkpoint")}`,
    `--recovery-path ${shellSingleQuote("manager can rerun manager-worker-progress and inspect assignment metadata")}`,
    `--source-ref ${shellSingleQuote(`assignment:${pairing.assignmentId}`)}`,
    `--source-ref ${shellSingleQuote(`task:${pairing.taskId}`)}`,
  ].join(" ");
  const questionCommand = [
    "node ./scripts/manager-ledger.mjs append-question --summary-json",
    `--run-id ${shellSingleQuote(pairing.runId)}`,
    ...(pairing.stateRoot ? [`--state-root ${shellSingleQuote(pairing.stateRoot)}`] : []),
    `--worker-id ${shellSingleQuote(pairing.workerId)}`,
    "--material-decision",
    `--summary ${shellSingleQuote("replace with the compact blocking question and options considered")}`,
    `--authority-basis ${shellSingleQuote("manager-owned-worker-material-question")}`,
    `--recovery-path ${shellSingleQuote("manager answers or routes the compact question; worker resumes after answer")}`,
    `--source-ref ${shellSingleQuote(`assignment:${pairing.assignmentId}`)}`,
    `--source-ref ${shellSingleQuote(`task:${pairing.taskId}`)}`,
  ].join(" ");
  return [
    "# Manager Worker Handoff",
    "",
    `workerId: ${pairing.workerId}`,
    `sessionName: ${pairing.sessionName}`,
    `assignmentId: ${pairing.assignmentId}`,
    `taskId: ${pairing.taskId}`,
    `branch: ${pairing.branch}`,
    `laneOwner: ${pairing.laneOwner || "(none)"}`,
    `phase: ${pairing.phase}`,
    "",
    "## Source Context",
    "",
    ...sourceContextLines,
    "",
    "## Instructions",
    "",
    "1. Stay within the assigned lane and repository/workspace gates.",
    "2. Inspect the assignment/worktree state before editing.",
    "3. Use BMAD/story instructions already attached to the lane when needed.",
    "4. Run focused verification for the changed surface.",
    "5. Report blockers, testable checkpoints, PR/delivery status, and risky decisions.",
    "6. Publish compact progress through the manager ledger, not raw pane output.",
    "7. Use the delegated lane owner shown above for workspace commands; do not take over fresh owners.",
    "8. Do not take over stale lanes, kill processes, access secrets, force-push, merge, or clean up without the existing gate and authority evidence.",
    ...reviewFeedbackInstructions,
    "",
    "## Progress Metadata",
    "",
    "Use this command after meaningful progress, verification, a user-testable checkpoint, or before waiting on the manager:",
    "",
    "```bash",
    checkpointCommand,
    "```",
    "",
    "Use this command only for a material blocking question that needs manager/operator judgment:",
    "",
    "```bash",
    questionCommand,
    "```",
    "",
    "## Start",
    "",
    `Run: node ./scripts/codex-workspace.mjs resume ${shellSingleQuote(pairing.assignmentId)}${ownerFlag}`,
    "",
  ].join("\n");
}

function workerHandoffSourceContextLines(pairing = {}) {
  const assignmentId = sanitizeLedgerField(pairing.assignmentId || "", "", 140);
  const lines = [];
  if (pairing.worktreePath) {
    lines.push(`worktreePath: ${pairing.worktreePath}`);
  }
  if (pairing.workerHandoff?.cwd) {
    lines.push(`managedWorkerCwd: ${pairing.workerHandoff.cwd}`);
  }
  if (assignmentId) {
    lines.push(`storyArtifact: ${resolve(repoRoot, "_bmad-output", "implementation-artifacts", `${assignmentId}.md`)}`);
  }
  if (pairing.reviewFindingsPath) {
    lines.push(`reviewFindingsPath: ${pairing.reviewFindingsPath}`);
  }
  lines.push(`sprintStatus: ${resolve(repoRoot, "_bmad-output", "implementation-artifacts", "sprint-status.yaml")}`);
  lines.push(`latestPrd: ${resolve(repoRoot, "_bmad-output", "planning-artifacts", "prds", "prd-Kendall_Nxt-2026-07-01", "prd.md")}`);
  lines.push("If an ignored BMAD artifact is absent from the managed worktree, read the absolute source artifact above from the main repo root and keep source refs in compact checkpoints.");
  return lines;
}

function pasteWorkerHandoff(pairing = {}, context = {}) {
  const runner = context.tmuxRunner || spawnSync;
  const load = runner("tmux", ["load-buffer", "-b", `${pairing.workerId}-handoff`, pairing.pastePath], { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
  if (load?.error) return { ok: false, error: load.error.message || "tmux load-buffer failed" };
  if ((load?.status ?? 0) !== 0) return { ok: false, error: String(load?.stderr || load?.stdout || "tmux load-buffer failed").trim(), status: load?.status };
  const target = resolveTmuxPaneTarget(pairing.sessionName, runner, context);
  if (!target.ok) return target;
  const paste = runner("tmux", ["paste-buffer", "-b", `${pairing.workerId}-handoff`, "-t", target.target], { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
  if (paste?.error) return { ok: false, error: paste.error.message || "tmux paste-buffer failed" };
  if ((paste?.status ?? 0) !== 0) return { ok: false, error: String(paste?.stderr || paste?.stdout || "tmux paste-buffer failed").trim(), status: paste?.status };
  const enter = sendTmuxEnterToTarget(target.target, runner, context);
  if (!enter.ok) return enter;
  const receipt = verifyTmuxPointerSubmitted(pairing, target.target, runner, context);
  if (!receipt.ok) return { ...receipt, sessionName: pairing.sessionName, paneTarget: target.target, submitKey: enter.submitKey || "C-m", bufferName: `${pairing.workerId}-handoff`, receipt };
  return { ok: true, sessionName: pairing.sessionName, paneTarget: target.target, submitKey: enter.submitKey || "C-m", bufferName: `${pairing.workerId}-handoff`, receipt };
}

function rebindManagedWorkerCwd(pairing = {}, paths = {}, options = {}, context = {}) {
  const cwd = sanitizeLedgerField(pairing.workerHandoff?.cwd || "", "", 260);
  if (!cwd) return { ok: true, status: "not_required" };
  const runner = context.tmuxRunner || spawnSync;
  const target = resolveTmuxPaneTarget(pairing.sessionName, runner, context);
  if (!target.ok) return target;
  const launchCommand = defaultWarmWorkerCommand(paths.proof?.state?.root || "", cwd).trim();
  if (!launchCommand) return { ok: false, error: "managed worker restart command is unavailable" };
  const respawn = runner("tmux", [
    "respawn-pane", "-k", "-t", target.target, "-c", cwd,
    "env", `CODEX_WORKSPACE_OWNER=${pairing.workerId}`, `CODEX_THREAD_ID=tmux-${pairing.sessionName}`,
    "bash", "-lc", launchCommand,
  ], { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
  if (respawn?.error) return { ok: false, error: respawn.error.message || "tmux respawn-pane failed" };
  if ((respawn?.status ?? 0) !== 0) return { ok: false, error: String(respawn?.stderr || respawn?.stdout || "tmux respawn-pane failed").trim(), status: respawn?.status };
  const inspected = runner("tmux", ["display-message", "-p", "-t", target.target, "#{pane_current_path}"], { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
  if (inspected?.error) return { ok: false, error: inspected.error.message || "tmux pane CWD inspection failed" };
  if ((inspected?.status ?? 0) !== 0) return { ok: false, error: String(inspected?.stderr || inspected?.stdout || "tmux pane CWD inspection failed").trim(), status: inspected?.status };
  const observedCwd = sanitizeLedgerField(String(inspected?.stdout || "").trim(), "", 260);
  if (!observedCwd) return { ok: false, error: "tmux worker CWD inspection returned no usable path" };
  return { ok: true, status: "rebound", cwd: observedCwd, expectedCwd: cwd, paneTarget: target.target };
}

function approveManagerPreWriteHandoff(pairing = {}, rebind = {}, context = {}) {
  if (!pairing.workerHandoff?.cwd) {
    return {
      status: "blocked",
      outcome: "decision_needed",
      reasonCode: "guard.admission_required",
      nextSafeAction: "Admit the source-change request, then start or resume its managed lane through codex-workspace before source edits.",
    };
  }
  return (context.preWriteGuard || approveManagedSourceWrite)({
    operation: "source_write",
    actualCwd: rebind.cwd,
    trustedLane: pairing.preWriteGuardEvidence,
  }, isPlainObject(context.preWriteGuardContext) ? context.preWriteGuardContext : {});
}

export function buildWorkerProgressStatus(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  const workerPacket = context.workerStatus || buildWorkerStatus(runOptions, context);
  const assignmentPacket = context.assignmentSummary || runWorkspaceJson(workspaceJsonArgs(["assignment-report", "--summary-json"], runOptions), context);
  const assignmentSummary = assignmentPacket.summary || assignmentPacket || {};
  const checkpoints = Array.isArray(context.checkpoints) ? context.checkpoints : readJson(paths.checkpoints, []);
  const questions = Array.isArray(context.questions) ? context.questions : readNdjsonStrict(paths.questions).value;
  const events = Array.isArray(context.events) ? context.events : readNdjsonStrict(paths.events).value;
  const answeredQuestionIds = answeredQuestionIdSet(events);
  const nowMs = context.now ? Date.parse(context.now) : Date.now();
  const staleSignalMs = Math.max(60_000, (nonNegativeInteger(options.progressStaleMinutes) ?? 3) * 60_000);
  const promptIdleGraceMs = Math.max(15_000, nonNegativeInteger(options.promptIdleGraceMs ?? context.promptIdleGraceMs) ?? 15_000);
  const workers = Array.isArray(workerPacket.summary?.workers) ? workerPacket.summary.workers.filter(isPlainObject).map(projectWorker) : [];
  const missingLiveWorkerIds = missingLiveWorkerIdsFromWorkerStatus(workerPacket);
  const liveWorkerEvidence = liveWorkerEvidenceFromWorkerStatus(workerPacket);
  const activeWorkers = workers.filter((worker) => worker.state === "active" && isManagerOwnedWorker(worker, runId) && !missingLiveWorkerIds.has(worker.workerId));
  const reportedLaneAssignments = Array.isArray(assignmentSummary.laneAssignments) ? assignmentSummary.laneAssignments : [];
  const fallbackLaneAssignments = readAssignmentFileLaneEvidence(runOptions.stateRoot || paths.proof.state?.root || "", assignmentSummary.currentOwner);
  const laneAssignments = fallbackLaneAssignments.length > 0
    ? mergeLaneEvidence(reportedLaneAssignments, fallbackLaneAssignments)
    : reportedLaneAssignments;
  const lanesByAssignment = new Map(laneAssignments.map((lane) => [String(lane.assignmentId || lane.assignment_id || ""), lane]));
  const promptProbe = options.promptIdle || options.warmReviewerProbe || context.promptProbe
    ? (context.promptProbe || buildWorkerPromptProbePlan(
        { ...runOptions, limit: 6, includeWarmReviewers: options.warmReviewerProbe === true },
        { ...context, workerStatus: workerPacket, includeWarmReviewers: options.warmReviewerProbe === true, now: context.now || runOptions.now || new Date(nowMs).toISOString() },
      ))
    : null;
  const promptProbes = Array.isArray(promptProbe?.summary?.probes) ? promptProbe.summary.probes : [];
  const promptIdleWorkerIds = new Set(
    promptProbes
      .filter((probe) => (probe.promptIdle === true || probe.promptDetected === true) && probe.inputHasManagerPointer !== true)
      .map((probe) => String(probe.workerId || ""))
      .filter(Boolean),
  );
  const reviewerReadinessByWorkerId = new Map(
    promptProbes
      .filter(isPlainObject)
      .map((probe) => [sanitizeLedgerField(probe.workerId || "", "", 80), projectReviewerReadiness({ reviewerReadiness: probe })])
      .filter(([workerId]) => Boolean(workerId)),
  );
  const workerProgress = activeWorkers.map((worker) => buildWorkerProgressRecord(worker, {
    lane: lanesByAssignment.get(worker.assignmentId || "") || null,
    checkpoints,
    questions,
    events,
    answeredQuestionIds,
    nowMs,
    staleSignalMs,
    promptIdleGraceMs,
    promptIdle: promptIdleWorkerIds.has(worker.workerId),
  }));
  const warmStateWorkers = workers.filter((worker) => isManagerOwnedWorker(worker, runId) && worker.state === "warm");
  const warmReviewerWorkers = warmStateWorkers.filter((worker) => !isManagerControlPlaneWorker(worker, runId) && isWarmReviewerCapacityRecord(worker));
  const warmReviewerEvaluations = warmReviewerWorkers.map((worker) => {
    const observation = reviewerReadinessByWorkerId.get(worker.workerId);
    const observedWorker = observation ? { ...worker, reviewerReadiness: observation } : worker;
    const promotionProjection = observation ? projectBootingWarmReviewerPromotion(observedWorker) : null;
    const eligibilityWorker = promotionProjection?.worker || observedWorker;
    const eligibility = buildWarmReviewerEligibility(eligibilityWorker, {
      runId,
      nowMs,
      maxAgeMs: Math.min(
        WARM_REVIEWER_READINESS_MAX_AGE_MS,
        Math.max(15_000, nonNegativeInteger(options.warmReviewerReadinessMaxAgeMs ?? context.warmReviewerReadinessMaxAgeMs) ?? WARM_REVIEWER_READINESS_MAX_AGE_MS),
      ),
      liveSession: liveWorkerEvidence.enforced
        ? (liveWorkerEvidence.workerIds.has(worker.workerId) && !missingLiveWorkerIds.has(worker.workerId)) ||
          (typeof context.tmuxRunner === "function" && observation?.captureOk === true &&
            observation.sessionName === worker.sessionName &&
            observation.resolvedSessionName === worker.sessionName)
        : observation?.captureOk === true &&
          observation.sessionName === worker.sessionName &&
          observation.resolvedSessionName === worker.sessionName,
    });
    return {
      worker: eligibilityWorker,
      eligibility: promotionProjection && eligibility.eligible
        ? { ...eligibility, promotionRequired: true, promotionEvidence: promotionProjection.evidence }
        : eligibility,
    };
  });
  const warmReviewerRows = warmReviewerEvaluations
    .filter(({ eligibility }) => eligibility.eligible)
    .map(({ worker, eligibility }) => buildWarmReviewerProgressRow(worker, eligibility));
  const warmReviewerEligibility = {
    warmCapacity: warmReviewerWorkers.length,
    eligibleCount: warmReviewerRows.length,
    unreadyCount: warmReviewerEvaluations.filter(({ eligibility }) => !eligibility.eligible).length,
    readinessMissingCount: warmReviewerEvaluations.filter(({ eligibility }) => !eligibility.positiveObservation).length,
    candidates: warmReviewerEvaluations.map(({ worker, eligibility }) => ({
      workerId: worker.workerId,
      ...eligibility,
    })),
    retention: "metadata_only_warm_reviewer_eligibility",
    rawPayloadRetained: false,
  };
  const attentionWorkers = workerProgress.filter((worker) => (
    ["prompt_idle_handoff", "needs_progress_signal", "checkpoint_stale", "question_answer_stale", "review_feedback_stale", "blocked_question", "checkpoint_blocked", "final_checkpoint_blocked", "owner_delegation_stale", "progress_signal_unanswered", "recovery_submit_unanswered", "pointer_receipt_unverified"].includes(worker.progressState)
    || (worker.progressState === "recovery_inspected" && worker.submitPendingAfterRecoveryInspection !== true)
    || needsPendingSubmitRepair(worker)
  ));
  return packet({
    status: attentionWorkers.length > 0 ? "attention" : "ready",
    summary: {
      runId,
      activeWorkers: activeWorkers.length,
      warmWorkers: warmStateWorkers.length,
      workerProgress,
      reviewerEligibleWorkers: warmReviewerRows,
      warmReviewerEligibility,
      finalCheckpointCounts: countWorkerFinalCheckpointStatuses(workerProgress),
      retention: "metadata_only_worker_progress",
      source: "manager-workers-checkpoints-questions-assignment-heartbeats",
    },
    warnings: attentionWorkers.length > 0 ? [{ code: "worker-progress-attention", message: `${attentionWorkers.length} active worker(s) need progress signal or question handling.` }] : [],
    nextActions: buildWorkerProgressNextActions(attentionWorkers, runOptions),
  });
}

export function buildLaneAdvancementPlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  const apply = options.apply === true;
  const limit = Math.max(1, Math.min(6, nonNegativeInteger(options.limit ?? context.limit) ?? 6));
  const workerPacket = context.workerStatus || buildWorkerStatus(runOptions, context);
  const assignmentPacket = context.assignmentSummary || runWorkspaceJson(workspaceJsonArgs(["assignment-report", "--summary-json"], runOptions), context);
  const assignmentSummary = assignmentPacket.summary || assignmentPacket || {};
  const checkpoints = Array.isArray(context.checkpoints) ? context.checkpoints : readJson(paths.checkpoints, []);
  const workers = Array.isArray(workerPacket.summary?.workers) ? workerPacket.summary.workers.filter(isPlainObject).map(projectWorker) : [];
  const reportedLaneAssignments = Array.isArray(assignmentSummary.laneAssignments) ? assignmentSummary.laneAssignments : [];
  const fallbackLaneAssignments = readAssignmentFileLaneEvidence(runOptions.stateRoot || paths.proof.state?.root || "", assignmentSummary.currentOwner);
  const laneAssignments = fallbackLaneAssignments.length > 0
    ? mergeLaneEvidence(reportedLaneAssignments, fallbackLaneAssignments)
    : reportedLaneAssignments;
  const lanesByAssignment = new Map(laneAssignments.map((lane) => [String(lane.assignmentId || lane.assignment_id || ""), lane]));
  const activeWorkers = workers.filter((worker) => worker.state === "active" && isManagerOwnedWorker(worker, runId));
  const seenReadyAssignmentIds = new Set();
  const readyLanes = activeWorkers
    .map((worker) => buildLaneAdvancementCandidate(worker, {
      lane: lanesByAssignment.get(worker.assignmentId || "") || null,
      checkpoints,
      managerContext: context,
    }))
    .filter(Boolean)
    .filter((lane) => {
      if (!isSafeCommandIdentifier(lane.assignmentId)) return false;
      if (seenReadyAssignmentIds.has(lane.assignmentId)) return false;
      seenReadyAssignmentIds.add(lane.assignmentId);
      return true;
    })
    .slice(0, limit);
  const applyReadyLanes = readyLanes.filter((lane) => lane.laneOwner);
  const ownerlessReadyLanes = readyLanes.filter((lane) => !lane.laneOwner);
  const blockers = [];
  if (!paths.proof.ok) {
    blockers.push({ code: "workspace-state-unsafe", message: paths.proof.error, nextAction: "Choose a safe workspace state root." });
  }
  if (blockers.length > 0) {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        apply,
        readyLaneCount: readyLanes.length,
        readyLanes,
        mutationMode: "none",
        retention: "metadata_only_lane_advancement_summary",
      },
      blockers,
    });
  }
  if (apply) {
    if (readyLanes.length === 0) {
      return packet({
        status: "ready",
        summary: {
          runId,
          apply: true,
          advancedLaneCount: 0,
          skippedLaneCount: 0,
          results: [],
          skippedLanes: [],
          mutationMode: "none; no ready lane at apply time",
          retention: "metadata_only_lane_advancement_apply_summary",
        },
        warnings: [{ code: "lane-advance-no-ready-lanes", message: "No active manager-owned lanes are ready for manager review or delivery advancement; treated as a no-op." }],
        nextActions: [{ code: "lane-advance-noop", summary: "No lane advancement was needed at apply time.", nextAction: "Continue worker progress monitoring." }],
      });
    }
    const skippedLanes = ownerlessReadyLanes
      .map((lane) => ({
        ...lane,
        status: "skipped",
        reason: "lane_owner_missing",
        nextAction: "Refresh assignment-report or assignment fallback metadata before applying lane advancement for this lane.",
      }));
    const results = applyReadyLanes.map((lane) => applyLaneAdvancementHeartbeat(lane, context, runOptions));
    const failed = results.filter((result) => !result.ok);
    const advancedCount = results.filter((result) => result.ok).length;
    const status = failed.length > 0 ? "blocked" : advancedCount > 0 ? "ready" : "attention";
    return packet({
      ok: failed.length === 0,
      status,
      summary: {
        runId,
        apply: true,
        advancedLaneCount: advancedCount,
        skippedLaneCount: skippedLanes.length,
        results,
        skippedLanes,
        mutationMode: "assignment_heartbeat_metadata_only",
        retention: "metadata_only_lane_advancement_apply_summary",
      },
      blockers: failed.map((result) => ({
        code: "lane-advance-heartbeat-failed",
        message: result.error || `Failed to advance ${result.assignmentId || "(unknown assignment)"}.`,
        nextAction: "Inspect owner-checked codex-workspace heartbeat evidence before retrying lane advancement.",
      })),
    });
  }
  return packet({
    status: readyLanes.length > 0 ? "attention" : "ready",
    summary: {
      runId,
      apply: false,
      readyLaneCount: readyLanes.length,
      readyLanes,
      continuousSelection: applyReadyLanes.length > 0 ? buildContinuousSelectionProof({
        code: "continuous-lane-advance-apply",
        mutationClass: "lane_advancement_heartbeat_metadata_only",
        runId,
        targets: applyReadyLanes,
      }) : null,
      mutationMode: "report_only_existing_delivery_gates_required",
      retention: "metadata_only_lane_advancement_summary",
      source: "manager-workers-checkpoints-assignment-metadata",
    },
    warnings: [
      ...(applyReadyLanes.length > 0 ? [{ code: "manager-lane-advance-ready", message: `${applyReadyLanes.length} active lane(s) appear ready for manager review or delivery.` }] : []),
      ...(ownerlessReadyLanes.length > 0 ? [{ code: "manager-lane-advance-owner-missing", message: `${ownerlessReadyLanes.length} review-ready lane(s) are missing owner metadata and cannot be auto-advanced.` }] : []),
    ],
    nextActions: applyReadyLanes.length > 0
      ? [
          {
            code: "manager-lane-advance-ready",
            summary: `Advance ${applyReadyLanes.length} owner-proven review-ready lane(s) into manager review/delivery metadata gates instead of pinging completed workers.`,
            nextAction: appendManagerCommandScope(`node ./scripts/manager-lane-advance.mjs --summary-json --limit ${applyReadyLanes.length}`, runOptions),
          },
        ]
      : ownerlessReadyLanes.length > 0
        ? [
            {
              code: "manager-lane-advance-owner-missing",
              summary: `${ownerlessReadyLanes.length} review-ready lane(s) need owner metadata before lane advancement can apply.`,
              nextAction: "Refresh assignment-report or assignment fallback metadata; continue other manager-owned worker actions.",
            },
          ]
        : [],
  });
}

function buildLaneAdvancementCandidate(worker = {}, context = {}) {
  const assignmentId = sanitizeIdentifierField(worker.assignmentId || "", "", 140);
  if (!assignmentId) return null;
  const openStoryReviewFeedback = buildOpenStoryReviewFeedbackSummary(assignmentId, context.managerContext || context);
  if (openStoryReviewFeedback.openCount > 0) return null;
  const lane = context.lane || {};
  const lanePhase = sanitizeLedgerField(lane.phase || lane.status || "", "", 80);
  if (["waiting_review", "reassignable", "closed"].includes(lanePhase)) return null;
  const lastHeartbeatMs = parseTimeMs(worker.lastHeartbeatAt);
  const checkpoints = filterWorkerProgressRecords(context.checkpoints, worker, assignmentId)
    .filter((record) => recordIsInWorkerAssignmentWindow(record, lastHeartbeatMs))
    .sort((left, right) => (parseTimeMs(right.timestamp) || 0) - (parseTimeMs(left.timestamp) || 0));
  const checkpoint = checkpoints.find((record) => classifyLaneAdvancementSummary(record.summary).state !== "not_ready");
  if (!checkpoint) return null;
  const rawFinalCheckpoint = latestFinalWorkerCheckpoint(checkpoints);
  const finalCheckpoint = validateWorkerFinalCheckpoint(rawFinalCheckpoint, worker, assignmentId);
  if (rawFinalCheckpoint && finalCheckpoint.status !== "ready") return null;
  const laneHeartbeatMs = parseTimeMs(lane.heartbeat || lane.lastHeartbeatAt || lane.last_heartbeat_at);
  const checkpointMs = parseTimeMs(checkpoint.timestamp);
  if (lanePhase === "in_progress" && laneHeartbeatMs && checkpointMs && laneHeartbeatMs > checkpointMs) {
    return null;
  }
  const readiness = classifyLaneAdvancementSummary(checkpoint.summary);
  const targetPhase = readiness.state === "delivery_gate_ready" ? "delivery_ready" : "review_ready";
  if (lanePhase === targetPhase) return null;
  return {
    assignmentId,
    taskId: sanitizeIdentifierField(worker.taskId || lane.taskId || lane.task_id || "", "", 140),
    workerId: sanitizeLedgerField(worker.workerId || "worker", "worker", 80),
    laneOwner: sanitizeLedgerField(lane.owner || worker.laneOwner || "", "", 160),
    lanePhase,
    targetPhase,
    readinessState: readiness.state,
    checkpointId: sanitizeLedgerField(checkpoint.checkpointId || checkpoint.id || "", "", 120),
    checkpointAt: sanitizeLedgerField(checkpoint.timestamp || "", "", 80),
    evidenceSummary: sanitizeLedgerField(checkpoint.summary || readiness.evidence, readiness.evidence, 220),
    finalCheckpoint,
    nextAction: "Run manager review, verification, delivery, finish-pr, merge, or cleanup only through existing codex-workspace and review gates.",
  };
}

function applyLaneAdvancementHeartbeat(lane = {}, context = {}, options = {}) {
  if (!isSafeCommandIdentifier(lane.assignmentId)) {
    return {
      ok: false,
      assignmentId: lane.assignmentId,
      targetPhase: lane.targetPhase,
      error: "lane advancement assignment id is not safe for workspace command routing",
    };
  }
  const args = [
    "heartbeat",
    lane.assignmentId,
    "--owner",
    lane.laneOwner,
    "--phase",
    lane.targetPhase || "review_ready",
    "--runner-kind",
    "manager-control-plane",
    "--current-command",
    "manager review/delivery queued",
    "--last-result",
    sanitizeLedgerField(lane.evidenceSummary || "lane ready for manager review", "lane ready for manager review", 180),
    "--json",
  ];
  const result = runWorkspaceJson(workspaceJsonArgs(args, options), context);
  if (result?.ok === false || result?.error) {
    return {
      ok: false,
      assignmentId: lane.assignmentId,
      targetPhase: lane.targetPhase,
      error: result.error || "codex-workspace heartbeat failed",
      ...(result.sandboxBoundary ? {
        failureClass: result.failureClass,
        sandboxBoundary: result.sandboxBoundary,
        sandboxSignatureClass: result.sandboxSignatureClass,
        rerunRequirement: result.rerunRequirement,
        sandboxBoundaryPacket: result.sandboxBoundaryPacket || null,
        safe_rerun: result.safe_rerun || "none",
        mutation: result.mutation || "unknown",
        retryStopLine: result.retryStopLine,
      } : {}),
    };
  }
  return {
    ok: true,
    assignmentId: lane.assignmentId,
    taskId: lane.taskId,
    workerId: lane.workerId,
    targetPhase: lane.targetPhase,
    mutation: "assignment heartbeat metadata only",
    heartbeat: {
      target: result.target || null,
      phase: result.phase || null,
      ownerMatches: result.ownerMatches === true,
      lastHeartbeatAt: result.lastHeartbeatAt || null,
    },
    statusUpdate: markManagerLaneStoryReviewReady(lane, options, context),
  };
}

function classifyLaneAdvancementSummary(summary = "") {
  const text = String(summary || "").toLowerCase();
  if (!text.trim()) return { state: "not_ready", evidence: "" };
  if (/\b(question|blocked|waiting|needs operator|failed|cannot proceed|error|in progress|still working|ongoing|partial|not complete|not ready)\b/.test(text)) {
    return { state: "not_ready", evidence: "checkpoint reports unresolved blocker" };
  }
  if (/\b(review[- ]ready|ready for manager review|ready for review|manager review|delegated code review complete|ready for delivery|verified and idle|verified,? ready|complete,? verified|complete and verified|lane remains complete|remains complete|complete,? verified,? and blocker-free|verified,? and blocker-free|implementation (?:is )?complete|implemented and verified|implemented\b.*\b(?:verification|tests?|checks?)\b.*\bpassed\b|(?:verification|tests?|checks?)\b.*\bpassed\b|staged implementation (?:remains )?unchanged|remains ready|ready for manager)\b/.test(text)) {
    const deliveryReady = /\b(ready for delivery|delivery[- ]ready|delivery gate ready)\b/.test(text);
    return { state: deliveryReady ? "delivery_gate_ready" : "manager_review_ready", evidence: "checkpoint indicates work is complete or review-ready" };
  }
  return { state: "not_ready", evidence: "" };
}

function classifyWorkerCheckpointBlockerSummary(summary = "") {
  const text = String(summary || "").toLowerCase();
  if (!text.trim()) return { blocked: false, reason: "" };
  if (/\b(blocked|blocking|cannot proceed|can't proceed|failed|failure|error|needs operator|waiting on|missing story|missing source|missing context|blocked_missing_story_context)\b/.test(text)) {
    return { blocked: true, reason: "checkpoint reports blocked or missing context" };
  }
  return { blocked: false, reason: "" };
}

const WORKER_FINAL_CHECKPOINT_REQUEST_STATES = new Set([
  "retired_clean_requested",
  "warm_available",
  "retirement_blocked",
]);

const WORKER_FINAL_CHECKPOINT_READY_DELIVERY_STATES = new Set([
  "delivered",
  "complete",
  "completed",
  "done",
  "closed",
  "parked",
]);

const WORKER_FINAL_CHECKPOINT_READY_PR_STATES = new Set([
  "merged",
  "closed",
  "not_applicable",
  "none",
  "parked",
]);

const WORKER_FINAL_CHECKPOINT_READY_MERGE_STATES = new Set([
  "merged",
  "closed",
  "not_applicable",
  "none",
  "parked",
]);

const WORKER_FINAL_CHECKPOINT_READY_CLEANUP_STATES = new Set([
  "complete",
  "cleanup_complete",
  "clean",
  "not_applicable",
  "none",
]);

const WORKER_FINAL_CHECKPOINT_REQUIRED_FIELDS = [
  "workerId",
  "assignmentId",
  "taskId",
  "branch",
  "diffSummary",
  "deliveryState",
  "prState",
  "mergeState",
  "cleanupState",
  "verificationSummary",
  "reviewSummary",
  "openQuestions",
  "unresolvedReviewThreads",
  "dirtyWorktree",
  "nextAssignmentReserved",
  "requestedFinalState",
  "recoveryPath",
  "openBlockers",
];

function countWorkerFinalCheckpointStatuses(workerProgress = []) {
  const counts = {
    missing: 0,
    incomplete: 0,
    blocked: 0,
    ready: 0,
    total: 0,
  };
  for (const worker of Array.isArray(workerProgress) ? workerProgress : []) {
    const status = String(worker?.finalCheckpoint?.status || "missing");
    if (Object.hasOwn(counts, status)) counts[status] += 1;
    counts.total += 1;
  }
  return counts;
}

function latestFinalWorkerCheckpoint(checkpoints = []) {
  return (Array.isArray(checkpoints) ? checkpoints : [])
    .filter(isPlainObject)
    .filter(isFinalWorkerCheckpoint)
    .sort((left, right) => (parseTimeMs(right.timestamp || right.finalCheckpoint?.timestamp || right.final_checkpoint?.timestamp) || 0) - (parseTimeMs(left.timestamp || left.finalCheckpoint?.timestamp || left.final_checkpoint?.timestamp) || 0))[0] || null;
}

function isFinalWorkerCheckpoint(checkpoint = {}) {
  if (!isPlainObject(checkpoint)) return false;
  if (isPlainObject(checkpoint.finalCheckpoint || checkpoint.final_checkpoint)) return true;
  const kind = normalizeWorkerLifecycleToken(checkpoint.kind || checkpoint.category || checkpoint.checkpointType || checkpoint.checkpoint_type || checkpoint.type || "");
  if (["worker_final_checkpoint", "final_worker_checkpoint", "final_checkpoint"].includes(kind)) return true;
  return Boolean(checkpoint.requestedFinalState || checkpoint.requested_final_state || checkpoint.finalState || checkpoint.final_state);
}

function workerFinalCheckpointValue(source = {}, ...keys) {
  for (const key of keys) {
    if (Object.hasOwn(source, key)) return source[key];
  }
  return undefined;
}

function finalCheckpointText(value, fallback = "", maxLength = 180) {
  return sanitizeLedgerField(value, fallback, maxLength) || fallback;
}

function finalCheckpointNumber(value) {
  if (value === undefined || value === null || value === "") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? Math.floor(parsed) : null;
}

function finalCheckpointBoolean(value) {
  if (value === undefined || value === null || value === "") return null;
  if (typeof value === "boolean") return value;
  const text = String(value || "").trim().toLowerCase();
  if (["true", "yes", "1"].includes(text)) return true;
  if (["false", "no", "0"].includes(text)) return false;
  return null;
}

function finalCheckpointRefs(value) {
  const refs = Array.isArray(value) ? value : value === undefined || value === null || value === "" ? [] : [value];
  return refs.map((ref) => sanitizeLedgerField(ref, "", 160)).filter(Boolean).slice(0, 12);
}

function finalCheckpointOpenBlockers(value) {
  if (!Array.isArray(value)) return [];
  return value.map((blocker) => {
    if (isPlainObject(blocker)) {
      const code = sanitizeLedgerField(blocker.code || blocker.reason || blocker.id || "open_blocker", "open_blocker", 120);
      const message = sanitizeLedgerField(blocker.message || blocker.summary || blocker.nextAction || code, code, 240);
      return `${code}:${message}`;
    }
    return sanitizeLedgerField(blocker, "", 240);
  }).filter(Boolean).slice(0, 12);
}

function canonicalWorkerFinalCheckpoint(checkpoint = {}, worker = {}, assignmentId = "") {
  const source = isPlainObject(checkpoint?.finalCheckpoint)
    ? checkpoint.finalCheckpoint
    : isPlainObject(checkpoint?.final_checkpoint)
      ? checkpoint.final_checkpoint
      : checkpoint;
  const openBlockersInput = workerFinalCheckpointValue(source, "openBlockers", "open_blockers", "blockers");
  return {
    checkpointId: finalCheckpointText(workerFinalCheckpointValue(source, "checkpointId", "checkpoint_id") || checkpoint.checkpointId || checkpoint.id || "", "", 120) || null,
    checkpointAt: finalCheckpointText(workerFinalCheckpointValue(source, "timestamp", "createdAt", "created_at") || checkpoint.timestamp || "", "", 80) || null,
    workerId: finalCheckpointText(workerFinalCheckpointValue(source, "workerId", "worker_id") || worker.workerId || "", "", 80) || null,
    assignmentId: finalCheckpointText(workerFinalCheckpointValue(source, "assignmentId", "assignment_id") || assignmentId || worker.assignmentId || "", "", 140) || null,
    taskId: finalCheckpointText(workerFinalCheckpointValue(source, "taskId", "task_id") || worker.taskId || "", "", 140) || null,
    branch: finalCheckpointText(workerFinalCheckpointValue(source, "branch", "branchName", "branch_name"), "", 160) || null,
    diffSummary: finalCheckpointText(workerFinalCheckpointValue(source, "diffSummary", "diff_summary", "changeSummary", "change_summary"), "", 240) || null,
    deliveryState: normalizeWorkerLifecycleToken(workerFinalCheckpointValue(source, "deliveryState", "delivery_state")),
    prState: normalizeWorkerLifecycleToken(workerFinalCheckpointValue(source, "prState", "pr_state", "pullRequestState", "pull_request_state")),
    prUrl: finalCheckpointText(workerFinalCheckpointValue(source, "prUrl", "pr_url", "pullRequestUrl", "pull_request_url"), "", 240) || null,
    parkedReason: finalCheckpointText(workerFinalCheckpointValue(source, "parkedReason", "parked_reason"), "", 180) || null,
    mergeState: normalizeWorkerLifecycleToken(workerFinalCheckpointValue(source, "mergeState", "merge_state")),
    cleanupState: normalizeWorkerLifecycleToken(workerFinalCheckpointValue(source, "cleanupState", "cleanup_state")),
    verificationSummary: finalCheckpointText(workerFinalCheckpointValue(source, "verificationSummary", "verification_summary", "verification"), "", 240) || null,
    reviewSummary: finalCheckpointText(workerFinalCheckpointValue(source, "reviewSummary", "review_summary", "review"), "", 240) || null,
    openQuestions: finalCheckpointNumber(workerFinalCheckpointValue(source, "openQuestions", "open_questions")),
    unresolvedReviewThreads: finalCheckpointNumber(workerFinalCheckpointValue(source, "unresolvedReviewThreads", "unresolved_review_threads")),
    dirtyWorktree: finalCheckpointBoolean(workerFinalCheckpointValue(source, "dirtyWorktree", "dirty_worktree")),
    nextAssignmentReserved: finalCheckpointBoolean(workerFinalCheckpointValue(source, "nextAssignmentReserved", "next_assignment_reserved")),
    requestedFinalState: normalizeWorkerLifecycleToken(workerFinalCheckpointValue(source, "requestedFinalState", "requested_final_state", "finalState", "final_state")),
    recoveryPath: finalCheckpointText(workerFinalCheckpointValue(source, "recoveryPath", "recovery_path", "nextSafeAction", "next_safe_action"), "", 240) || null,
    openBlockersPresent: openBlockersInput !== undefined,
    openBlockersWellFormed: openBlockersInput === undefined || Array.isArray(openBlockersInput),
    openBlockers: finalCheckpointOpenBlockers(openBlockersInput),
    sourceRefs: finalCheckpointRefs(workerFinalCheckpointValue(source, "sourceRefs", "source_refs") || checkpoint.sourceRefs || checkpoint.source_refs),
    rawPayloadRetained: false,
  };
}

function validateWorkerFinalCheckpoint(checkpoint = null, worker = {}, assignmentId = "") {
  if (!isPlainObject(checkpoint)) {
    return {
      status: "missing",
      requestedFinalState: null,
      handoffQuality: "poor",
      missingFields: WORKER_FINAL_CHECKPOINT_REQUIRED_FIELDS,
      blockers: [{ code: "no_final_checkpoint", message: "No compact final worker checkpoint is present." }],
      mutation: "none",
      rawPayloadRetained: false,
    };
  }
  const canonical = canonicalWorkerFinalCheckpoint(checkpoint, worker, assignmentId);
  const missingFields = WORKER_FINAL_CHECKPOINT_REQUIRED_FIELDS.filter((field) => {
    if (field === "openBlockers") return canonical.openBlockersPresent !== true || canonical.openBlockersWellFormed !== true;
    return canonical[field] === null || canonical[field] === undefined || canonical[field] === "";
  });
  if (!canonical.prUrl && !canonical.parkedReason) missingFields.push("prUrlOrParkedReason");
  if (!WORKER_FINAL_CHECKPOINT_REQUEST_STATES.has(canonical.requestedFinalState)) missingFields.push("requestedFinalState");
  const blockers = [];
  if (missingFields.length > 0) {
    blockers.push({
      code: "no_final_checkpoint",
      message: `Final checkpoint is missing required field(s): ${[...new Set(missingFields)].join(", ")}.`,
      missingFields: [...new Set(missingFields)],
    });
  }
  if (canonical.openQuestions > 0) {
    blockers.push({ code: "material_question_open", message: `${canonical.openQuestions} material question(s) remain open.` });
  }
  if (canonical.unresolvedReviewThreads > 0) {
    blockers.push({ code: "review_threads_unresolved", message: `${canonical.unresolvedReviewThreads} review thread(s) remain unresolved.` });
  }
  if (canonical.dirtyWorktree === true) {
    blockers.push({ code: "dirty_worktree", message: "Final checkpoint reports a dirty worktree." });
  }
  if (canonical.nextAssignmentReserved === true) {
    blockers.push({ code: "handoff_pending", message: "Final checkpoint reports a reserved next assignment." });
  }
  if (canonical.workerId && worker.workerId && canonical.workerId !== worker.workerId) {
    blockers.push({ code: "identity_ambiguous", message: "Final checkpoint worker id does not match the active worker." });
  }
  if (canonical.assignmentId && assignmentId && canonical.assignmentId !== assignmentId) {
    blockers.push({ code: "identity_ambiguous", message: "Final checkpoint assignment id does not match the active assignment." });
  }
  if (canonical.taskId && worker.taskId && canonical.taskId !== worker.taskId) {
    blockers.push({ code: "identity_ambiguous", message: "Final checkpoint task id does not match the active task." });
  }
  if (canonical.deliveryState && !WORKER_FINAL_CHECKPOINT_READY_DELIVERY_STATES.has(canonical.deliveryState)) {
    blockers.push({ code: "blocked_state_mismatch", message: `Delivery state ${canonical.deliveryState} is not final.` });
  }
  if (canonical.cleanupState && !WORKER_FINAL_CHECKPOINT_READY_CLEANUP_STATES.has(canonical.cleanupState)) {
    blockers.push({ code: "cleanup_not_done", message: `Cleanup state is ${canonical.cleanupState}.` });
  }
  if (canonical.prState && !WORKER_FINAL_CHECKPOINT_READY_PR_STATES.has(canonical.prState)) {
    blockers.push({ code: "pr_checks_pending", message: `PR state ${canonical.prState} is not final.` });
  }
  if (canonical.mergeState && !WORKER_FINAL_CHECKPOINT_READY_MERGE_STATES.has(canonical.mergeState)) {
    blockers.push({ code: "pr_checks_pending", message: `Merge state ${canonical.mergeState} is not final.` });
  }
  if (["pending", "queued", "running", "in_progress", "waiting"].includes(canonical.prState) || ["pending", "queued", "running", "in_progress", "waiting"].includes(canonical.mergeState)) {
    blockers.push({ code: "pr_checks_pending", message: "PR or merge state is still pending." });
  }
  if (["failed", "failure", "error", "blocked"].includes(canonical.prState) || ["failed", "failure", "error", "blocked"].includes(canonical.mergeState)) {
    blockers.push({ code: "pr_checks_failing", message: "PR or merge state reports failure." });
  }
  if (/\b(inconclusive|timeout|timed out|sandbox|failed|failure|error)\b/i.test(canonical.verificationSummary || "")) {
    blockers.push({ code: "verification_inconclusive", message: "Verification summary is inconclusive or failed." });
  }
  if (canonical.openBlockers.length > 0) {
    blockers.push({ code: "reachable_root_present", message: "Final checkpoint reports open blocker/root evidence.", blockers: canonical.openBlockers });
  }
  const evidenceBlockers = blockers.filter((blocker) => blocker.code !== "no_final_checkpoint");
  if (evidenceBlockers.length > 0 && canonical.requestedFinalState !== "retirement_blocked") {
    blockers.push({ code: "blocked_state_mismatch", message: "Blocked evidence requires requestedFinalState retirement_blocked." });
  } else if (missingFields.length === 0 && evidenceBlockers.length === 0 && canonical.requestedFinalState === "retirement_blocked") {
    blockers.push({ code: "blocked_state_mismatch", message: "requestedFinalState retirement_blocked has no blocker evidence." });
  }
  const status = missingFields.length > 0 ? "incomplete" : blockers.length > 0 ? "blocked" : "ready";
  return {
    status,
    requestedFinalState: canonical.requestedFinalState || null,
    handoffQuality: status === "ready" ? "complete" : canonical.recoveryPath ? "partial" : "poor",
    checkpoint: canonical,
    missingFields: [...new Set(missingFields)],
    blockers,
    mutation: "none",
    rawPayloadRetained: false,
  };
}

function buildWorkerProgressNextActions(workers = [], options = {}) {
  const attentionWorkers = Array.isArray(workers) ? workers : [];
  const signalableStates = new Set(["prompt_idle_handoff", "needs_progress_signal", "checkpoint_stale", "question_answer_stale", "review_feedback_stale", "owner_delegation_stale"]);
  const questionWorkers = attentionWorkers.filter((worker) => ["blocked_question", "checkpoint_blocked"].includes(worker.progressState));
  const finalCheckpointWorkers = attentionWorkers.filter((worker) => worker.progressState === "final_checkpoint_blocked");
  const signalableWorkers = attentionWorkers.filter((worker) => signalableStates.has(worker.progressState));
  const pendingSubmitWorkers = attentionWorkers.filter(needsPendingSubmitRepair);
  let signalActionAdded = false;
  let pendingSubmitActionAdded = false;
  let questionActionAdded = false;
  let finalCheckpointActionAdded = false;
  const actions = [];
  if (questionWorkers.length > 0) {
    actions.push(buildWorkerQuestionAnswerNextAction(questionWorkers, options));
    questionActionAdded = true;
  }
  for (const worker of attentionWorkers) {
    if (["blocked_question", "checkpoint_blocked"].includes(worker.progressState) && questionActionAdded) {
      continue;
    }
    if (worker.progressState === "final_checkpoint_blocked") {
      if (!finalCheckpointActionAdded) {
        actions.push(buildWorkerFinalCheckpointNextAction(finalCheckpointWorkers, options));
        finalCheckpointActionAdded = true;
      }
      continue;
    }
    if (needsPendingSubmitRepair(worker)) {
      if (!pendingSubmitActionAdded) {
        actions.push(buildWorkerSubmitPendingNextAction(pendingSubmitWorkers, options));
        pendingSubmitActionAdded = true;
      }
      continue;
    }
    if (signalableStates.has(worker.progressState)) {
      if (!signalActionAdded) {
        actions.push(buildWorkerProgressSignalNextAction(signalableWorkers, options));
        signalActionAdded = true;
      }
      continue;
    }
    actions.push(buildWorkerProgressNextAction(worker, options));
  }
  return actions;
}

function needsPendingSubmitRepair(worker = {}) {
  const receiptNeedsSubmit = worker.progressState === "pointer_receipt_unverified";
  const progressSignalNeedsSubmit = worker.progressState === "progress_signal_sent"
    && Number(worker.latestProgressSignalAgeSeconds || 0) >= 120
    && worker.submitPendingAfterProgressSignal !== true
    && Number(worker.questionCount || 0) === 0;
  const recoveryInspectionNeedsSubmit = worker.progressState === "recovery_inspected"
    && worker.submitPendingAfterRecoveryInspection !== true
    && Number(worker.questionCount || 0) === 0;
  return receiptNeedsSubmit || progressSignalNeedsSubmit || recoveryInspectionNeedsSubmit;
}

function buildWorkerSubmitPendingNextAction(workers = [], options = {}) {
  const selected = Array.isArray(workers) ? workers.filter(isPlainObject) : [];
  const targetFlags = selected.length === 1 ? workerExactTargetFlags(selected[0]) : "";
  return {
    code: "worker-submit-pending-progress-signal",
    summary: `Submit pending prompts for ${selected.length || 1} manager-owned worker(s).`,
    nextAction: appendManagerCommandScope(`node ./scripts/manager-worker-submit-pending.mjs --summary-json${targetFlags || ` --limit ${selected.length || 1}`}`, options),
  };
}

function buildWorkerQuestionAnswerNextAction(workers = [], options = {}) {
  const selected = Array.isArray(workers) ? workers.filter(isPlainObject) : [];
  const targetFlags = selected.length === 1 ? workerExactTargetFlags(selected[0]) : "";
  return {
    code: "worker-progress-blocked_question",
    summary: `Answer ${selected.length || 1} compact worker question(s).`,
    nextAction: appendManagerCommandScope(`node ./scripts/manager-worker-answer-question.mjs --summary-json${targetFlags || ` --limit ${selected.length || 1}`}`, options),
  };
}

function buildWorkerFinalCheckpointNextAction(workers = [], options = {}) {
  const selected = Array.isArray(workers) ? workers.filter(isPlainObject) : [];
  return {
    code: "worker-progress-final_checkpoint_blocked",
    summary: `Resolve ${selected.length || 1} final checkpoint contract blocker(s).`,
    nextAction: appendManagerCommandScope("route final checkpoint blockers through manager review, cleanup, worker feedback, or recovery before retirement/reuse", options),
  };
}

function buildWorkerProgressSignalNextAction(workers = [], options = {}) {
  const selected = Array.isArray(workers) ? workers.filter(isPlainObject) : [];
  const first = selected[0] || {};
  if (selected.length <= 1) {
    return buildWorkerProgressNextAction(first, { ...options, limit: 1 });
  }
  const states = [...new Set(selected.map((worker) => String(worker.progressState || "attention")).filter(Boolean))];
  const promptIdle = states.includes("prompt_idle_handoff");
  return {
    code: states.length === 1 ? `worker-progress-${states[0]}` : "worker-progress-signal-batch",
    summary: `Signal ${selected.length} active worker(s) for compact metadata progress.`,
    nextAction: appendManagerCommandScope(`node ./scripts/manager-worker-progress-signal.mjs --summary-json --limit ${selected.length}${promptIdle ? " --prompt-idle" : ""}`, options),
  };
}

function buildWorkerProgressNextAction(worker = {}, context = {}) {
  const code = `worker-progress-${worker.progressState}`;
  const summary = `${worker.workerId} ${String(worker.progressState || "attention").replaceAll("_", " ")} for ${worker.assignmentId || "unassigned"}.`;
  if (["prompt_idle_handoff", "needs_progress_signal", "checkpoint_stale", "question_answer_stale", "review_feedback_stale", "owner_delegation_stale"].includes(worker.progressState)) {
    const limit = Math.max(1, Number(context.limit || 0) || Number(context.index || 0) + 1);
    const targetFlags = workerExactTargetFlags(worker);
    return {
      code,
      summary,
      nextAction: appendManagerCommandScope(`node ./scripts/manager-worker-progress-signal.mjs --summary-json${targetFlags || ` --limit ${limit}`}${worker.progressState === "prompt_idle_handoff" ? " --prompt-idle" : ""}`, context),
    };
  }
  if (worker.progressState === "progress_signal_unanswered") {
    return {
      code,
      summary,
      nextAction: appendManagerCommandScope("node ./scripts/manager-worker-recovery-inspection.mjs --summary-json", context),
    };
  }
  if (worker.progressState === "recovery_submit_unanswered") {
    const limit = Math.max(1, Number(context.limit || 0) || Number(context.index || 0) + 1);
    const targetFlags = workerExactTargetFlags(worker);
    return {
      code,
      summary,
      nextAction: appendManagerCommandScope(`node ./scripts/manager-worker-retire.mjs --summary-json${targetFlags || ` --limit ${limit}`}`, context),
    };
  }
  return {
    code,
    summary,
    nextAction: worker.nextAction,
  };
}

function workerExactTargetFlags(worker = {}) {
  if (!isPlainObject(worker)) return "";
  const flags = [];
  const entries = [
    ["worker-id", worker.workerId || worker.worker_id],
    ["session-name", worker.sessionName || worker.session_name],
    ["assignment-id", worker.assignmentId || worker.assignment_id || worker.laneId || worker.lane_id],
    ["task-id", worker.taskId || worker.task_id],
  ];
  for (const [flag, value] of entries) {
    const normalized = sanitizeContinuousFlagValue(value);
    if (normalized) flags.push(`--${flag} ${shellSingleQuote(normalized)}`);
  }
  return flags.length > 0 ? ` ${flags.join(" ")}` : "";
}

function workerMatchesExactTarget(worker = {}, options = {}) {
  if (!isPlainObject(worker)) return false;
  const checks = [
    [options.workerId, worker.workerId || worker.worker_id],
    [options.sessionName, worker.sessionName || worker.session_name],
    [options.assignmentId, worker.assignmentId || worker.assignment_id || worker.laneId || worker.lane_id],
    [options.taskId, worker.taskId || worker.task_id],
  ].filter(([expected]) => String(expected || "").trim());
  return checks.every(([expected, actual]) => String(actual || "") === String(expected || ""));
}

function continuousCommandExactWorkerTarget(command = "") {
  const target = {};
  for (const [flag, key] of [
    ["worker-id", "workerId"],
    ["session-name", "sessionName"],
    ["assignment-id", "assignmentId"],
    ["task-id", "taskId"],
  ]) {
    const match = String(command || "").match(new RegExp(`\\s--${flag}(?:=|\\s+)(?:'([^']*)'|"([^"]*)"|([^\\s]+))`));
    const value = match ? sanitizeContinuousFlagValue(match[1] || match[2] || match[3] || "") : "";
    if (value) target[key] = value;
  }
  return target;
}

function filterWorkersByExactTarget(workers = [], options = {}) {
  const rows = Array.isArray(workers) ? workers.filter(isPlainObject) : [];
  const hasExactTarget = Boolean(options.workerId || options.sessionName || options.assignmentId || options.taskId);
  return hasExactTarget ? rows.filter((worker) => workerMatchesExactTarget(worker, options)) : rows;
}

function exactTargetLimit(options = {}, fallback = 0) {
  if (options.workerId || options.sessionName || options.assignmentId || options.taskId) return 1;
  return fallback;
}

export function buildWorkerRecoveryInspection(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const progress = context.progressStatus || buildWorkerProgressStatus(runOptions, context);
  const workerProgress = Array.isArray(progress.summary?.workerProgress) ? progress.summary.workerProgress : [];
  const unanswered = workerProgress.filter((worker) => worker.progressState === "progress_signal_unanswered");
  const inspections = unanswered.map((worker) => ({
    workerId: worker.workerId,
    sessionName: worker.sessionName,
    assignmentId: worker.assignmentId,
    taskId: worker.taskId,
    laneOwner: worker.laneOwner,
    recoveryState: worker.recoveryState,
    progressSignalCount: worker.progressSignalCount,
    latestProgressSignalAgeSeconds: worker.latestProgressSignalAgeSeconds,
    latestCheckpointAgeSeconds: worker.latestCheckpointAgeSeconds,
    checkpointCount: worker.checkpointCount,
    questionCount: worker.questionCount,
    eventCount: worker.eventCount,
    diagnosis: "progress signal was sent repeatedly without a newer manager checkpoint",
    nextAction: "Do not send another progress request. Use the repaired C-m submit path for future sends, then choose a bounded manager-owned repair, retire, or restart action if this worker remains silent.",
  }));
  if (runOptions.apply && inspections.length > 0) {
    ledgerCommand({
      command: "append-event",
      runId,
      stateRoot: runOptions.stateRoot,
      eventType: "worker_recovery_inspection",
      authorityBasis: "metadata-only-worker-recovery-inspection",
      summary: `Inspected ${inspections.length} unanswered manager-owned worker progress signal(s).`,
      sourceRefs: inspections.flatMap((inspection) => [
        `assignment:${inspection.assignmentId}`,
        `worker:${inspection.workerId}`,
      ]),
      evidenceRefs: inspections.map((inspection) => `worker-recovery-inspection:${inspection.workerId}`),
      recoveryPath: "choose bounded manager-owned repair, retire, restart, or wait for checkpoint; do not send another progress request",
    }, context);
  }
  return packet({
    status: inspections.length > 0 ? "attention" : "ready",
    summary: {
      runId,
      apply: Boolean(runOptions.apply),
      mutation: runOptions.apply && inspections.length > 0 ? "manager-ledger-worker-recovery-inspection-event" : "none",
      inspectedWorkers: inspections.length,
      activeWorkers: progress.summary?.activeWorkers || 0,
      warmWorkers: progress.summary?.warmWorkers || 0,
      inspections,
      continuousSelection: inspections.length > 0 ? buildContinuousSelectionProof({
        code: "continuous-worker-recovery-inspection",
        mutationClass: "metadata_only_worker_recovery_inspection",
        runId,
        targets: inspections,
      }) : null,
      retention: "metadata_only_worker_recovery_inspection",
      source: "manager-worker-progress-status",
    },
    warnings: inspections.length > 0
      ? [{ code: "worker-recovery-inspection-needed", message: `${inspections.length} active worker(s) have unanswered progress signals.` }]
      : [],
    nextActions: inspections.length > 0
      ? [{
          code: "worker-submit-path-repaired",
          summary: "The tmux submit transport now sends explicit C-m; avoid more signal churn until workers produce checkpoints or a bounded repair lane is chosen.",
          nextAction: "Run node ./scripts/manager-worker-progress.mjs --summary-json after the next worker checkpoint window.",
        }]
      : [{ code: "worker-recovery-clear", summary: "No unanswered worker progress signal requires recovery inspection.", nextAction: "Continue metadata-only worker monitoring." }],
  });
}

export function buildWorkerProgressSignalPlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  const progress = context.progressStatus || buildWorkerProgressStatus(runOptions, context);
  const signalableStates = runOptions.promptIdle
    ? ["prompt_idle_handoff", "needs_progress_signal", "checkpoint_stale", "question_answer_stale", "review_feedback_stale", "owner_delegation_stale"]
    : ["needs_progress_signal", "checkpoint_stale", "question_answer_stale", "review_feedback_stale", "owner_delegation_stale"];
  const candidates = Array.isArray(progress.summary?.workerProgress)
    ? filterWorkersByExactTarget(progress.summary.workerProgress, runOptions).filter((worker) => signalableStates.includes(worker.progressState))
    : [];
  const limit = exactTargetLimit(runOptions, runOptions.limit === null || runOptions.limit === undefined ? candidates.length : Math.max(0, Number(runOptions.limit) || 0));
  const selected = candidates.slice(0, limit).map((worker) => buildWorkerProgressSignalRequest(worker, paths));
  if (progress.status !== "attention" || selected.length === 0) {
    return packet({
      status: "ready",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", staleWorkers: candidates.length, requests: [] },
      nextActions: [{ code: "worker-progress-signal-not-needed", summary: "No stale manager-owned worker progress signal is needed.", nextAction: "Continue metadata-only monitoring." }],
    });
  }
  if (!runOptions.apply) {
    const targetFlags = selected.length === 1 ? workerExactTargetFlags(selected[0]) : "";
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        staleWorkers: candidates.length,
        planned: selected.length,
        requests: selected,
        continuousSelection: buildContinuousSelectionProof({
          code: runOptions.promptIdle ? "continuous-worker-prompt-idle-progress-signal" : "continuous-worker-progress-signal",
          mutationClass: "manager_owned_worker_progress_signal",
          runId,
          targets: selected,
        }),
        transport: { primary: "durable_progress_request_file", secondary: "literal_safe_tmux_buffer", pastedText: "read_progress_request_file_path_only" },
      },
      nextActions: [{ code: "worker-progress-signal-apply-ready", summary: `Signal ${selected.length} stale active worker(s) for compact metadata progress.`, nextAction: `node ./scripts/manager-worker-progress-signal.mjs --summary-json${targetFlags || ` --limit ${selected.length}`}${runOptions.promptIdle ? " --prompt-idle" : ""} --apply` }],
    });
  }
  mkdirSync(join(paths.root, "progress-requests"), { recursive: true });
  const results = [];
  for (const request of selected) {
    writeFileSync(request.requestPath, renderWorkerProgressSignalFile(request));
    writeFileSync(request.pastePath, `${request.pasteText}\n`);
    const paste = pasteWorkerProgressSignal(request, context);
    const recoverableUnverifiedReceipt = paste.ok !== true &&
      paste.receipt?.checked === true &&
      paste.receipt.verified === false &&
      paste.receipt.repaired === true;
    results.push({ ...request, status: paste.ok || recoverableUnverifiedReceipt ? "progress_signal_sent" : "failed", paste });
  }
  for (const result of results.filter((candidate) => candidate.paste?.receipt?.checked === true && candidate.paste.receipt.verified === false)) {
    recordPointerReceiptFailure(runOptions, result, context, "progress-signal");
  }
  const failed = results.find((result) => result.status === "failed");
  if (failed) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "partial", results },
      blockers: [{ code: "worker-progress-signal-paste-failed", message: failed.paste?.error || `Failed to paste progress signal to ${failed.sessionName}.`, nextAction: "Inspect manager progress request files and tmux paste result before retrying." }],
    });
  }
  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_progress_signal_apply",
    authorityBasis: "manager-owned-worker-progress-signal-existing-gates",
    summary: `Sent ${results.length} manager-owned worker progress signal(s).`,
    sourceRefs: results.flatMap((result) => [`assignment:${result.assignmentId}`, `worker:${result.workerId}`, ...receiptSourceRefs(result)]),
    evidenceRefs: results.map((result) => `progress-request:${result.requestPath || result.workerId || result.assignmentId}`),
    recoveryPath: "rerun manager-worker-progress and inspect progress request files before retrying",
  }, context);
  return packet({
    status: "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-progress-request-file-and-tmux-buffer",
      results,
      continuousSelection: buildContinuousSelectionProof({
        code: runOptions.promptIdle ? "continuous-worker-prompt-idle-progress-signal" : "continuous-worker-progress-signal",
        mutationClass: "manager_owned_worker_progress_signal",
        runId,
        targets: results,
      }),
      retention: "progress_request_path_and_summary",
    },
  });
}

export function buildWorkerReviewFeedbackPlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  const progress = context.progressStatus || buildWorkerProgressStatus(runOptions, context);
  const allowedProgressStates = runOptions.assignmentId || runOptions.workerId
    ? ["manager_review_ready", "delivery_gate_ready", "checkpoint_seen", "checkpoint_stale", "checkpoint_blocked"]
    : ["manager_review_ready", "delivery_gate_ready", "checkpoint_seen", "checkpoint_stale"];
  const rawFindingsFile = runOptions.reviewFindingsFile;
  const findingsPath = resolveReviewFindingsPath(rawFindingsFile, paths);
  const findingsAssignmentId = assignmentIdFromReviewFindingsPath(findingsPath, paths);
  const candidates = Array.isArray(progress.summary?.workerProgress)
    ? progress.summary.workerProgress
      .filter((worker) => allowedProgressStates.includes(worker.progressState))
      .filter((worker) => !workerProgressRowConflictsManagerOwner(worker, runId))
      .filter((worker) => !runOptions.assignmentId || worker.assignmentId === runOptions.assignmentId)
      .filter((worker) => !runOptions.workerId || worker.workerId === runOptions.workerId)
      .filter((worker) => !findingsAssignmentId || worker.assignmentId === findingsAssignmentId)
    : [];
  if (!findingsPath) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", requests: [] },
      blockers: [{ code: "review-feedback-findings-missing", message: "Review feedback requires --review-findings-file pointing to the compact failed review result under this manager run.", nextAction: "Use the matching review-results/<assignment-id>.md file from the current manager run." }],
    });
  }
  if (!findingsAssignmentId || !reviewResultIsFail(findingsPath)) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", findingsPath, requests: [] },
      blockers: [{ code: "review-feedback-findings-invalid", message: "Review feedback can only route a failed delegated review result for a matching manager-owned assignment.", nextAction: "Use the failed review-results/<assignment-id>.md artifact produced by manager-worker-code-review." }],
    });
  }
  const retentionBlocker = reviewFindingsRetentionBlocker(findingsPath);
  if (retentionBlocker) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", findingsPath, requests: [], rawPayloadRetained: false },
      blockers: [retentionBlocker],
    });
  }
  if (runOptions.apply) {
    const release = releaseTerminalWorkerReviewReservation(paths, assignmentIdForStoryKey(findingsAssignmentId), context);
    if (!release.ok) {
      return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none; failed-review reservation release failed" }, blockers: [{ code: "worker-code-review-reservation-release-failed", message: release.error || "Failed-review reservation could not be released.", nextAction: "Repair authoritative workers.json before feedback routing." }] });
    }
  }
  const selected = candidates.slice(0, Math.max(0, runOptions.limit ?? 1)).map((worker) => buildWorkerReviewFeedbackRequest(worker, paths, findingsPath));
  if (selected.length === 0) {
    return packet({
      status: "ready",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", reviewReadyWorkers: candidates.length, requests: [] },
      warnings: [{ code: "review-feedback-no-target-worker", message: "No matching manager-owned review-ready worker was found for review feedback." }],
      nextActions: [{ code: "review-feedback-not-needed", summary: "No review feedback target is ready.", nextAction: "Continue metadata-only monitoring or rerun with a matching --assignment-id." }],
    });
  }
  if (!runOptions.apply) {
    const scopedStateRoot = runOptions.stateRoot ? ` --state-root ${shellSingleQuote(runOptions.stateRoot)}` : "";
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        planned: selected.length,
        requests: selected,
        transport: { primary: "durable_review_feedback_file", secondary: "literal_safe_tmux_buffer", pastedText: "read_review_feedback_file_path_only" },
      },
      nextActions: [{ code: "worker-review-feedback-apply-ready", summary: `Route review feedback to ${selected.length} manager-owned worker(s).`, nextAction: `node ./scripts/manager-worker-review-feedback.mjs --summary-json --run-id ${shellSingleQuote(runId)}${scopedStateRoot} --assignment-id ${shellSingleQuote(selected[0].assignmentId)} --worker-id ${shellSingleQuote(selected[0].workerId)} --limit ${selected.length} --apply --review-findings-file ${shellSingleQuote(findingsPath)}` }],
    });
  }
  const metadataPreflight = selected
    .map((request) => ({ request, validation: validateWorkerReviewFeedbackMetadata(request, runOptions, context) }))
    .find((entry) => entry.validation.ok === false);
  if (metadataPreflight) {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        apply: true,
        mutation: "none",
        findingsPath,
        requests: selected,
        failedRequest: sanitizeCyclePacketValue(metadataPreflight.request),
      },
      blockers: [{
        code: metadataPreflight.validation.code || "review-feedback-metadata-invalid",
        message: metadataPreflight.validation.message || "Review feedback metadata could not be validated before worker mutation.",
        nextAction: metadataPreflight.validation.nextAction || "Refresh manager worker progress, sprint status, and workspace owner metadata before retrying.",
      }],
    });
  }
  mkdirSync(join(paths.root, "review-feedback"), { recursive: true });
  const findings = readFileSync(findingsPath, "utf8");
  const results = [];
  for (const request of selected) {
    writeFileSync(request.requestPath, renderWorkerReviewFeedbackFile(request, findings));
    writeFileSync(request.pastePath, `${request.pasteText}\n`);
    const heartbeat = refreshReviewFeedbackAssignmentHeartbeat(request, runOptions, context);
    const paste = heartbeat?.ok === true ? pasteWorkerPointer(request, `${request.workerId}-review-feedback`, context) : null;
    const statusUpdate = paste?.ok === true ? markManagerReviewFeedbackInProgress(request, runOptions, context) : null;
    const metadataOk = heartbeat?.ok === true && paste?.ok === true && !statusUpdate?.skipped;
    results.push({ ...request, status: metadataOk && paste?.ok === true ? "review_feedback_sent" : "failed", paste, statusUpdate, heartbeat });
  }
  const failed = results.find((result) => result.status === "failed");
  if (failed) {
    recordPointerReceiptFailure(runOptions, failed, context, "review-feedback");
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "partial", results },
      blockers: [{ code: "worker-review-feedback-apply-incomplete", message: failed.paste?.error || failed.heartbeat?.error || failed.statusUpdate?.reason || `Failed to route review feedback completely to ${failed.sessionName}.`, nextAction: "Inspect manager review feedback files, tmux paste result, sprint status, and assignment heartbeat before retrying." }],
    });
  }
  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_review_feedback_apply",
    authorityBasis: "manager-owned-worker-review-feedback-existing-gates",
    summary: `Sent ${results.length} manager-owned worker review feedback packet(s).`,
    sourceRefs: results.flatMap((result) => [`assignment:${result.assignmentId}`, `worker:${result.workerId}`, ...receiptSourceRefs(result)]),
    evidenceRefs: results.map((result) => `review-feedback:${result.requestPath || result.workerId || result.assignmentId}`),
    recoveryPath: "rerun manager-worker-progress and inspect review feedback files before retrying",
  }, context);
  return packet({
    status: "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-review-feedback-file-and-tmux-buffer",
      results,
      retention: "review_feedback_path_and_summary",
    },
  });
}

function revalidateWarmReviewerBeforeApply(reviewer = {}, targetAssignmentId = "", runOptions = {}, context = {}) {
  if (reviewer?.reviewerEligibility?.eligible !== true || reviewer?.reviewerEligibility?.proofState !== "eligible") {
    return { ok: true, skipped: true, reviewer };
  }
  const paths = managerRunPaths(runOptions.runId, runOptions, context);
  const workerRead = readJsonArray(paths.workers);
  const authoritative = workerRead.value.filter(isPlainObject).map(projectWorker)
    .find((worker) => worker.workerId === reviewer.workerId && worker.sessionName === reviewer.sessionName && worker.owner === reviewer.owner);
  const allowedReservationId = sanitizeLedgerField(context.allowedReviewReservationId || "", "", 140);
  const reservationMatches = allowedReservationId && authoritative?.reviewReservation?.reservationId === allowedReservationId;
  const sampledAt = new Date().toISOString();
  const sampledNowMs = Date.parse(sampledAt);
  const probe = authoritative
    ? probeWorkerInputRegion(authoritative, context.tmuxRunner || spawnSync, { ...context, now: sampledAt })
    : null;
  const latestAuthoritative = readJsonArray(paths.workers).value.filter(isPlainObject).map(projectWorker)
    .find((worker) => worker.workerId === reviewer.workerId && worker.sessionName === reviewer.sessionName);
  const authoritativeChangedDuringProbe = workerReviewCoordinationFingerprint(authoritative) !== workerReviewCoordinationFingerprint(latestAuthoritative);
  const eligibilityWorker = authoritative && reservationMatches ? { ...authoritative, reviewReservation: null } : authoritative;
  const observedWorker = eligibilityWorker && probe
    ? { ...eligibilityWorker, reviewerReadiness: projectReviewerReadiness({ reviewerReadiness: probe }) }
    : null;
  const promotionProjection = reviewer?.reviewerEligibility?.promotionRequired === true
    ? projectBootingWarmReviewerPromotion(observedWorker)
    : null;
  const projectedEligibilityWorker = promotionProjection?.worker || observedWorker;
  const eligibility = projectedEligibilityWorker
    ? buildWarmReviewerEligibility(projectedEligibilityWorker, {
        runId: runOptions.runId,
        nowMs: sampledNowMs,
        maxAgeMs: WARM_REVIEWER_READINESS_MAX_AGE_MS,
        liveSession: probe.captureOk === true,
      })
    : null;
  const refreshed = authoritative && !authoritativeChangedDuringProbe && eligibility?.eligible
    ? buildWarmReviewerProgressRow(
        { ...projectedEligibilityWorker, reviewReservation: reservationMatches ? authoritative.reviewReservation : null },
        promotionProjection ? { ...eligibility, promotionRequired: true, promotionEvidence: promotionProjection.evidence } : eligibility,
      )
    : null;
  const target = normalizeBmadStoryAssignmentId(targetAssignmentId || "") || sanitizeLedgerField(targetAssignmentId || "", "", 140);
  const assignmentHistory = appendWorkerAssignmentHistory(
    appendWorkerAssignmentHistory(refreshed?.assignmentHistory || [], { assignmentId: authoritative?.previousAssignmentId, taskId: authoritative?.previousTaskId }),
    { assignmentId: authoritative?.assignmentId, taskId: authoritative?.taskId },
  )
    .map((entry) => normalizeBmadStoryAssignmentId(entry.assignmentId || "") || sanitizeLedgerField(entry.assignmentId || "", "", 140));
  const originalPaneTarget = sanitizeLedgerField(reviewer.reviewerEligibility?.paneTarget || "", "", 40);
  if (
    !refreshed ||
    refreshed.reviewerEligibility?.eligible !== true ||
    refreshed.reviewerEligibility?.proofState !== "eligible" ||
    (target && assignmentHistory.includes(target)) ||
    (originalPaneTarget && refreshed.reviewerEligibility?.paneTarget !== originalPaneTarget)
  ) {
    return {
      ok: false,
      skipped: false,
      blocker: {
        code: "worker-code-review-reviewer-readiness-changed",
        message: "Warm reviewer readiness, live-session ownership, assignment, or lease evidence changed before review-pointer apply.",
        nextAction: "Refresh bounded warm reviewer readiness and delegated review planning; do not paste the review pointer or warm more capacity.",
      },
      progress: { summary: { sampledAt, source: "authoritative_workers_json_and_live_pane_probe", workerPath: paths.workers } },
    };
  }
  return { ok: true, skipped: false, reviewer: refreshed, sampledAt };
}

function workerReviewCoordinationFingerprint(worker = {}) {
  if (!worker) return "missing";
  return JSON.stringify({
    workerId: worker.workerId || null,
    owner: worker.owner || null,
    runId: worker.runId || null,
    sessionName: worker.sessionName || null,
    state: worker.state || null,
    lifecycleState: worker.lifecycleState || null,
    assignmentState: worker.assignmentState || null,
    assignmentId: worker.assignmentId || null,
    taskId: worker.taskId || null,
    previousAssignmentId: worker.previousAssignmentId || null,
    previousTaskId: worker.previousTaskId || null,
    assignmentHistory: appendWorkerAssignmentHistory(worker.assignmentHistory || [], {}),
    leaseId: worker.leaseId || null,
    leaseState: worker.leaseState || null,
    currentLease: worker.currentLease || null,
    reviewReservation: worker.reviewReservation || null,
    takeoverRequired: worker.takeoverRequired === true,
    takeoverAmbiguous: worker.takeoverAmbiguous === true,
    takeoverState: worker.takeoverState || null,
    pendingRequest: worker.pendingRequest === true,
    requestState: worker.requestState || null,
    busy: worker.busy === true,
    booting: worker.booting === true,
  });
}

function reserveWorkerCodeReviewer(paths, runId, reviewer = {}, request = {}, context = {}) {
  return withWorkerAssignmentLock(paths, context, () => {
    const workerRead = readJsonArray(paths.workers);
    if (workerRead.warning) return { ok: false, error: workerRead.warning.message };
    const records = workerRead.value.filter(isPlainObject);
    const index = records.findIndex((worker) => worker.workerId === reviewer.workerId && worker.sessionName === reviewer.sessionName && worker.owner === reviewer.owner);
    if (index < 0) return { ok: false, error: "Reviewer disappeared from authoritative workers.json before reservation." };
    const now = new Date();
    const existingReservation = records[index].reviewReservation;
    const existingInactive = reservationHasPositiveInactivity(existingReservation);
    const existingTerminal = reservationHasFreshTerminalResult(existingReservation);
    const existingCancelled = ["cancelled", "canceled", "released", "expired"].includes(normalizeWorkerLifecycleToken(existingReservation?.state));
    if (existingReservation && (existingInactive || existingTerminal || existingCancelled)) delete records[index].reviewReservation;
    let reservationReviewer = reviewer;
    let promotionRollback = null;
    if (reviewer?.reviewerEligibility?.promotionRequired === true) {
      const beforePromotion = projectWorker(records[index]);
      const sampledAt = new Date().toISOString();
      const probe = probeWorkerInputRegion(beforePromotion, context.tmuxRunner || spawnSync, { ...context, now: sampledAt });
      const latest = readJsonArray(paths.workers).value.filter(isPlainObject).map(projectWorker)
        .find((worker) => worker.workerId === beforePromotion.workerId && worker.sessionName === beforePromotion.sessionName);
      const observed = { ...beforePromotion, reviewerReadiness: projectReviewerReadiness({ reviewerReadiness: probe }) };
      const promotionProjection = projectBootingWarmReviewerPromotion(observed);
      const eligibility = promotionProjection
        ? buildWarmReviewerEligibility(promotionProjection.worker, {
            runId,
            nowMs: Date.parse(sampledAt),
            maxAgeMs: WARM_REVIEWER_READINESS_MAX_AGE_MS,
            liveSession: probe.captureOk === true,
          })
        : null;
      if (
        workerReviewCoordinationFingerprint(beforePromotion) !== workerReviewCoordinationFingerprint(latest) ||
        !promotionProjection || !eligibility?.eligible
      ) {
        return { ok: false, error: "Booting reviewer readiness or coordination state changed before atomic promotion and reservation." };
      }
      promotionRollback = {
        recoveryState: { present: Object.hasOwn(records[index], "recoveryState"), value: records[index].recoveryState },
        recoveryAction: { present: Object.hasOwn(records[index], "recoveryAction"), value: records[index].recoveryAction },
        lifecycleState: { present: Object.hasOwn(records[index], "lifecycleState"), value: records[index].lifecycleState },
        booting: { present: Object.hasOwn(records[index], "booting"), value: records[index].booting },
        reviewerPromotionEvidence: { present: Object.hasOwn(records[index], "reviewerPromotionEvidence"), value: records[index].reviewerPromotionEvidence },
      };
      records[index] = {
        ...records[index],
        recoveryState: "recovered_warm",
        recoveryAction: "await_dispatcher_lease_pull",
        lifecycleState: "warm_available",
        booting: false,
        reviewerPromotionEvidence: promotionProjection.evidence,
      };
      reservationReviewer = buildWarmReviewerProgressRow(
        { ...promotionProjection.worker, reviewerPromotionEvidence: promotionProjection.evidence },
        { ...eligibility, promotionRequired: false, promotionEvidence: promotionProjection.evidence },
      );
    }
    const projected = projectWorker(records[index]);
    if (projected.reviewReservation || hasActiveWorkerLease(projected) || projected.assignmentId || projected.taskId || workerHasPendingRequest(projected) || workerHasTakeoverAmbiguity(projected) || projected.busy === true) {
      return { ok: false, error: "Reviewer gained an assignment, lease, reservation, request, busy state, or takeover ambiguity before paste." };
    }
    const targetAssignmentId = sanitizeLedgerField(request.targetAssignmentId || "", "", 140);
    const reservationId = `review:${runId}:${reviewer.workerId}:${targetAssignmentId}`;
    records[index] = {
      ...records[index],
      reviewReservation: {
        reservationId,
        targetAssignmentId,
        workerId: reservationReviewer.workerId,
        owner: reservationReviewer.owner,
        runId,
        sessionName: reservationReviewer.sessionName,
        paneTarget: reservationReviewer.reviewerEligibility?.paneTarget || null,
        state: "reserved",
        reservedAt: now.toISOString(),
        expiresAt: new Date(now.getTime() + WORKER_REVIEW_RESERVATION_MAX_AGE_MS).toISOString(),
        requestPath: sanitizeLedgerField(request.requestPath || "", "", 320) || null,
        resultPath: sanitizeLedgerField(request.resultPath || "", "", 320) || null,
      },
    };
    writeFileSync(paths.workers, `${JSON.stringify(records, null, 2)}\n`);
    const persisted = readJsonArray(paths.workers).value.find((worker) => worker?.workerId === reviewer.workerId)?.reviewReservation;
    if (persisted?.reservationId !== reservationId) return { ok: false, error: "Reviewer reservation was not authoritatively persisted." };
    return { ok: true, reservationId, reviewer: reservationReviewer, promotionPersisted: Boolean(promotionRollback), promotionRollback };
  });
}

function reservationHasFreshTerminalResult(reservation = {}) {
  if (!reservation.resultPath || !reviewResultHasTerminalStatus(reservation.resultPath)) return false;
  const resultMs = safeMtimeMs(reservation.resultPath);
  const requestMs = reservation.requestPath ? safeMtimeMs(reservation.requestPath) : 0;
  const reservedMs = parseTimeMs(reservation.reservedAt) || 0;
  const nowMs = Date.now();
  return resultMs > 0 && resultMs >= Math.max(requestMs, reservedMs) && resultMs <= nowMs;
}

function reservationHasPositiveInactivity(reservation = {}) {
  const metadata = reservation.recoveryMetadata || {};
  const confirmedMs = parseTimeMs(metadata.inactiveConfirmedAt || reservation.inactiveConfirmedAt);
  const reservedMs = parseTimeMs(reservation.reservedAt);
  const nowMs = Date.now();
  return confirmedMs > 0 && reservedMs > 0 && confirmedMs >= reservedMs && confirmedMs <= nowMs && nowMs - confirmedMs <= WARM_REVIEWER_READINESS_MAX_AGE_MS &&
    metadata.reservationId === reservation.reservationId && metadata.workerId === reservation.workerId && metadata.owner === reservation.owner &&
    metadata.sessionName === reservation.sessionName && metadata.runId === reservation.runId &&
    metadata.paneTarget === reservation.paneTarget;
}

function rollbackWorkerCodeReviewReservation(paths, reviewer = {}, reservationId = "", context = {}) {
  return withWorkerAssignmentLock(paths, context, () => {
    const workerRead = readJsonArray(paths.workers);
    if (workerRead.warning) return { ok: false, error: workerRead.warning.message };
    const records = workerRead.value.filter(isPlainObject);
    const index = records.findIndex((worker) => worker.workerId === reviewer.workerId && worker.reviewReservation?.reservationId === reservationId);
    if (index < 0) return { ok: false, error: "Authoritative reviewer reservation was missing during rollback." };
    const { reviewReservation: _removed, ...rest } = records[index];
    records[index] = rest;
    const promotionRollback = context.promotionRollback;
    if (isPlainObject(promotionRollback)) {
      for (const field of ["recoveryState", "recoveryAction", "lifecycleState", "booting", "reviewerPromotionEvidence"]) {
        const snapshot = promotionRollback[field];
        if (!isPlainObject(snapshot)) continue;
        if (snapshot.present === true) records[index][field] = snapshot.value;
        else delete records[index][field];
      }
    }
    writeFileSync(paths.workers, `${JSON.stringify(records, null, 2)}\n`);
    const persisted = readJsonArray(paths.workers).value.find((worker) => worker?.workerId === reviewer.workerId)?.reviewReservation;
    return persisted ? { ok: false, error: "Reviewer reservation rollback did not persist." } : { ok: true };
  });
}

function releaseTerminalWorkerReviewReservation(paths, targetAssignmentId = "", context = {}) {
  return withWorkerAssignmentLock(paths, context, () => {
    const workerRead = readJsonArray(paths.workers);
    if (workerRead.warning) return { ok: false, error: workerRead.warning.message };
    const records = workerRead.value.filter(isPlainObject);
    let released = 0;
    for (const record of records) {
      const reservation = record.reviewReservation;
      if (!reservation || reservation.targetAssignmentId !== targetAssignmentId) continue;
      if (!reservationHasFreshTerminalResult(reservation)) continue;
      delete record.reviewReservation;
      released += 1;
    }
    if (released > 0) writeFileSync(paths.workers, `${JSON.stringify(records, null, 2)}\n`);
    return { ok: true, released };
  });
}

function recoverInactiveWorkerReviewReservations(paths, context = {}) {
  return withWorkerAssignmentLock(paths, context, () => {
    const workerRead = readJsonArray(paths.workers);
    if (workerRead.warning) return { ok: false, error: workerRead.warning.message };
    const records = workerRead.value.filter(isPlainObject);
    const nowMs = Date.now();
    let released = 0;
    for (const record of records) {
      const reservation = record.reviewReservation;
      if (!reservation) continue;
      const terminal = reservationHasFreshTerminalResult(reservation);
      const inactive = reservationHasPositiveInactivity(reservation);
      const cancelled = ["cancelled", "canceled", "released", "expired"].includes(normalizeWorkerLifecycleToken(reservation.state));
      if (!terminal && !inactive && !cancelled) continue;
      delete record.reviewReservation;
      released += 1;
    }
    if (released > 0) writeFileSync(paths.workers, `${JSON.stringify(records, null, 2)}\n`);
    return { ok: true, released };
  });
}

function projectBootingWarmReviewerPromotion(worker = {}) {
  if (worker.state !== "warm" || worker.recoveryState !== "restarted_booting") return null;
  if (workerHasTakeoverAmbiguity(worker) || workerHasPendingRequest(worker) || worker.busy === true || worker.assignmentId || worker.taskId || hasActiveWorkerLease(worker) || reviewReservationBlocksWorker(worker)) return null;
  const lifecycleState = normalizeWorkerLifecycleToken(worker.lifecycleState || "");
  if (lifecycleState && !["warm", "warm_available"].includes(lifecycleState)) return null;
  const projected = {
    ...worker,
    recoveryState: "recovered_warm",
    recoveryAction: "await_dispatcher_lease_pull",
    lifecycleState: "warm_available",
    booting: false,
  };
  if (!classifyWarmReviewerLifecycle(projected).eligible) return null;
  const readiness = isPlainObject(projected.reviewerReadiness) ? projected.reviewerReadiness : {};
  return {
    worker: projected,
    evidence: {
      source: sanitizeLedgerField(readiness.source || WARM_REVIEWER_READINESS_SOURCE, WARM_REVIEWER_READINESS_SOURCE, 100),
      observedAt: sanitizeLedgerField(readiness.observedAt || "", "", 80) || null,
      sessionName: sanitizeLedgerField(projected.sessionName || "", "", 80) || null,
      paneTarget: sanitizeLedgerField(readiness.paneTarget || "", "", 40) || null,
      currentCommand: sanitizeLedgerField(readiness.currentCommand || "", "", 80) || null,
      rawPayloadRetained: false,
    },
  };
}

function markWorkerReviewReservationDispatched(paths, reviewer = {}, reservationId = "", proof = {}, context = {}) {
  return withWorkerAssignmentLock(paths, context, () => {
    const workerRead = readJsonArray(paths.workers);
    if (workerRead.warning) return { ok: false, error: workerRead.warning.message };
    const records = workerRead.value.filter(isPlainObject);
    const index = records.findIndex((worker) => worker.workerId === reviewer.workerId && worker.reviewReservation?.reservationId === reservationId);
    if (index < 0) return { ok: false, error: "Reviewer reservation disappeared after paste." };
    records[index].reviewReservation = {
      ...records[index].reviewReservation,
      state: "dispatched",
      dispatchedAt: new Date().toISOString(),
      paneTarget: sanitizeLedgerField(proof.paneTarget || "", "", 40) || null,
      sessionName: sanitizeLedgerField(proof.sessionName || reviewer.sessionName || "", "", 80) || null,
    };
    writeFileSync(paths.workers, `${JSON.stringify(records, null, 2)}\n`);
    return { ok: true };
  });
}

function writeJsonAtomically(pathValue, value) {
  const temporaryPath = `${pathValue}.tmp-${process.pid}-${Date.now()}`;
  try {
    writeFileSync(temporaryPath, `${JSON.stringify(value, null, 2)}\n`);
    renameSync(temporaryPath, pathValue);
  } finally {
    try {
      rmSync(temporaryPath, { force: true });
    } catch {
      // Best effort only; the authoritative target was never replaced by this cleanup.
    }
  }
}

function writeWorkerRecordsAtomically(paths, records = [], context = {}, phase = "worker_state") {
  const writeDefault = () => writeJsonAtomically(paths.workers, records);
  if (typeof context.workerRecordsWriter === "function") {
    return context.workerRecordsWriter({ path: paths.workers, records, phase, writeDefault });
  }
  writeDefault();
  return { ok: true };
}

function markWorkerReviewDeliveryRecoveryRequired(paths, reviewer = {}, reservationId = "", proof = {}, context = {}) {
  return withWorkerAssignmentLock(paths, context, () => {
    const workerRead = readJsonArray(paths.workers);
    if (workerRead.warning) return { ok: false, error: workerRead.warning.message };
    const records = workerRead.value.filter(isPlainObject);
    const index = records.findIndex((worker) => worker.workerId === reviewer.workerId && worker.reviewReservation?.reservationId === reservationId);
    if (index < 0) return { ok: false, error: "Authoritative reviewer reservation disappeared after ambiguous delivery." };
    const reservation = records[index].reviewReservation;
    records[index].reviewReservation = {
      ...reservation,
      state: "delivery_recovery_required",
      recoveryMetadata: {
        reservationId,
        workerId: reviewer.workerId,
        owner: reviewer.owner,
        runId: reservation.runId,
        sessionName: reservation.sessionName,
        paneTarget: sanitizeLedgerField(proof.paneTarget || reservation.paneTarget || "", "", 40) || null,
        deliveryState: "ambiguous",
        recoveryAction: "inspect_review_delivery_before_retry",
        recordedAt: new Date().toISOString(),
      },
    };
    try {
      writeWorkerRecordsAtomically(paths, records, context, "review_delivery_recovery_required");
      return { ok: true };
    } catch (error) {
      const fallback = persistReviewDeliveryRecoveryFallback(paths, records[index], proof, error);
      return { ok: false, error: error?.message || "Ambiguous delivery recovery state could not be persisted.", ...fallback };
    }
  });
}

function persistReviewDeliveryRecoveryFallback(paths, worker = {}, proof = {}, persistenceError = null) {
  const reservation = worker.reviewReservation || {};
  const fallbackPath = join(paths.root, "review-delivery-recovery", `${sanitizeIdentifierField(reservation.reservationId || worker.workerId || "unknown", "unknown", 140)}.json`);
  try {
    mkdirSync(dirname(fallbackPath), { recursive: true });
    writeJsonAtomically(fallbackPath, {
      schemaVersion: "worker-review-delivery-recovery.v1",
      reservationId: reservation.reservationId || null,
      workerId: worker.workerId || null,
      owner: worker.owner || null,
      runId: worker.runId || null,
      sessionName: reservation.sessionName || worker.sessionName || null,
      paneTarget: sanitizeLedgerField(proof.paneTarget || reservation.paneTarget || "", "", 40) || null,
      deliveryState: "ambiguous",
      recoveryAction: "repair_workers_json_and_inspect_exact_reviewer_pane",
      persistenceError: sanitizeLedgerField(persistenceError?.message || String(persistenceError || "unknown"), "unknown", 240),
      recordedAt: new Date().toISOString(),
      rawPayloadRetained: false,
    });
    return { fallbackPersisted: true, fallbackPath };
  } catch (fallbackError) {
    return { fallbackPersisted: false, fallbackPath, fallbackError: fallbackError?.message || String(fallbackError || "fallback persistence failed") };
  }
}

export function buildWorkerCodeReviewPlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  if (runOptions.apply) {
    const recovery = recoverInactiveWorkerReviewReservations(paths, context);
    if (!recovery.ok) {
      return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none; reviewer reservation recovery failed" }, blockers: recovery.blockers?.length ? recovery.blockers : [{ code: "worker-code-review-reservation-recovery-failed", message: recovery.error || "Inactive reviewer reservations could not be recovered.", nextAction: "Repair authoritative workers.json before review apply." }] });
    }
  }
  const requestedStoryKey = normalizeBmadStoryAssignmentId(runOptions.assignmentId || "") || sanitizeLedgerField(runOptions.storyKey || "", "", 140);
  const reviewOptions = requestedStoryKey ? { ...runOptions, storyKey: requestedStoryKey, allowExplicitReviewReadyAssignment: true } : runOptions;
  const progress = context.progressStatus || buildWorkerProgressStatus({ ...runOptions, warmReviewerProbe: true }, context);
  const reviewPlan = context.reviewRequestPlan || buildBmadCodeReviewRequestPlan(reviewOptions, { ...context, progressStatus: progress });
  if (reviewPlan.ok === false || reviewPlan.status === "blocked" || !reviewPlan.summary?.selectedStory?.storyKey) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", requests: [] },
      blockers: reviewPlan.blockers?.length
        ? reviewPlan.blockers
        : [{ code: "worker-code-review-no-review-story", message: "No BMAD review story is ready to delegate.", nextAction: "Refresh manager-cycle-packet and lane advancement state." }],
    });
  }

  const rows = [
    ...(Array.isArray(progress.summary?.workerProgress) ? progress.summary.workerProgress : []),
    ...(Array.isArray(progress.summary?.reviewerEligibleWorkers)
      ? progress.summary.reviewerEligibleWorkers.filter((worker) => (
          worker?.reviewerEligibility?.eligible === true &&
          worker?.reviewerEligibility?.proofState === "eligible"
        ))
      : []),
  ];
  const targetStoryKey = sanitizeLedgerField(reviewPlan.summary.selectedStory.storyKey, "", 140);
  const targetAssignmentId = assignmentIdForStoryKey(targetStoryKey);
  const target = rows.find((worker) => normalizeBmadStoryAssignmentId(worker.assignmentId || "") === targetStoryKey) || {
    assignmentId: targetAssignmentId,
    taskId: "",
    workerId: "",
    sessionName: "",
    worktreePath: "",
  };
  const freshness = buildWorkerCodeReviewFreshness({ paths, targetAssignmentId, target }, runOptions, context);
  const reviewAttemptSummary = buildWorkerCodeReviewAttemptSummary({ paths, targetAssignmentId, invalidatorMs: freshness.latestInvalidatorMs }, runOptions, context);
  const freshResultPath = join(paths.root, "review-results", `${targetAssignmentId}.md`);
  const freshResultFailed = freshness.resultFresh === true ? reviewResultIsFail(freshResultPath) : false;
  const freshResultRetentionBlocker = freshResultFailed ? reviewFindingsRetentionBlocker(freshResultPath) : null;
  if (freshness.resultFresh === true && !freshResultRetentionBlocker) {
    if (runOptions.apply) {
      const release = releaseTerminalWorkerReviewReservation(paths, targetAssignmentId, context);
      if (!release.ok) {
        return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none; terminal reservation release failed" }, blockers: [{ code: "worker-code-review-reservation-release-failed", message: release.error || "Terminal reviewer reservation could not be released.", nextAction: "Repair authoritative workers.json before assigning more work to the reviewer." }] });
      }
    }
    const scopedStateRoot = runOptions.stateRoot ? ` --state-root ${shellSingleQuote(runOptions.stateRoot)}` : "";
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: Boolean(runOptions.apply),
        mutation: "none; fresh delegated review result exists",
        planned: 0,
        alreadyPrepared: true,
        requestExists: freshness.requestMtimeMs > 0,
        requestFresh: freshness.requestFresh,
        requestContractFresh: freshness.requestFresh,
        resultExists: true,
        resultFresh: true,
        resultFailed: freshResultFailed,
        resultComplete: true,
        resultPath: freshResultPath,
        reviewFreshness: sanitizeCyclePacketValue(freshness),
        reviewAttemptSummary: sanitizeCyclePacketValue(reviewAttemptSummary),
        requests: [],
        results: runOptions.apply ? [{ status: "fresh_review_result_exists", resultPath: freshResultPath }] : undefined,
        retention: "review_result_path_and_summary",
      },
      nextActions: [{
        code: freshResultFailed ? "worker-code-review-failed-result-ready" : "worker-code-review-result-ready",
        summary: freshResultFailed
          ? "Fresh delegated worker code review result failed; route compact findings back to the owning worker."
          : "Fresh delegated worker code review result exists; route findings or delivery next.",
        nextAction: freshResultFailed
          ? `node ./scripts/manager-worker-review-feedback.mjs --summary-json --run-id ${shellSingleQuote(runId)}${scopedStateRoot} --assignment-id ${shellSingleQuote(targetAssignmentId)} --review-findings-file ${shellSingleQuote(freshResultPath)}`
          : `Review compact findings at ${freshResultPath}.`,
      }],
    });
  }
  const reviewer = selectWorkerCodeReviewer(rows, targetAssignmentId, runOptions.workerId, reviewAttemptSummary, runId, target.workerId);
  if (!reviewer) {
    const warmReviewerEligibility = isPlainObject(progress.summary?.warmReviewerEligibility)
      ? progress.summary.warmReviewerEligibility
      : null;
    const warmReadinessHeld = Boolean(
      warmReviewerEligibility &&
      warmReviewerEligibility.warmCapacity > 0 &&
      warmReviewerEligibility.unreadyCount > 0,
    );
    const requestedWorkerId = sanitizeLedgerField(runOptions.workerId || "", "", 80);
    const requestedRow = requestedWorkerId ? rows.find((worker) => worker.workerId === requestedWorkerId) : null;
    const authoritativeWorkers = readJsonArray(paths.workers).value.filter(isPlainObject).map(projectWorker);
    const authoritativeRequested = requestedWorkerId ? authoritativeWorkers.find((worker) => worker.workerId === requestedWorkerId) : null;
    const exhaustedWorkers = new Set(sourceRefList(reviewAttemptSummary.exhaustedWorkers || []));
    const history = appendWorkerAssignmentHistory(
      appendWorkerAssignmentHistory(authoritativeRequested?.assignmentHistory || requestedRow?.assignmentHistory || [], { assignmentId: authoritativeRequested?.previousAssignmentId, taskId: authoritativeRequested?.previousTaskId }),
      { assignmentId: authoritativeRequested?.assignmentId, taskId: authoritativeRequested?.taskId },
    )
      .map((entry) => normalizeBmadStoryAssignmentId(entry.assignmentId || "") || sanitizeLedgerField(entry.assignmentId || "", "", 140));
    const selfReviewRow = authoritativeRequested || requestedRow;
    const requestedSelfReview = Boolean(selfReviewRow && (
      selfReviewRow.workerId === target.workerId ||
      normalizeBmadStoryAssignmentId(selfReviewRow.assignmentId || "") === targetStoryKey ||
      normalizeBmadStoryAssignmentId(selfReviewRow.previousAssignmentId || "") === targetStoryKey ||
      history.includes(targetStoryKey)
    ));
    const candidateIds = [...new Set([
      ...rows.map((worker) => sanitizeLedgerField(worker?.workerId || "", "", 80)),
      ...(Array.isArray(warmReviewerEligibility?.candidates) ? warmReviewerEligibility.candidates : [])
        .map((candidate) => sanitizeLedgerField(candidate?.workerId || "", "", 80)),
      requestedWorkerId,
    ].filter(Boolean))];
    const candidateRows = candidateIds.map((workerId) => (
      authoritativeWorkers.find((worker) => worker.workerId === workerId) || rows.find((worker) => worker.workerId === workerId)
    )).filter(Boolean);
    const selfReviewCandidates = candidateRows.filter((worker) => {
      const candidateHistory = appendWorkerAssignmentHistory(
        appendWorkerAssignmentHistory(worker.assignmentHistory || [], { assignmentId: worker.previousAssignmentId, taskId: worker.previousTaskId }),
        { assignmentId: worker.assignmentId, taskId: worker.taskId },
      ).map((entry) => normalizeBmadStoryAssignmentId(entry.assignmentId || "") || sanitizeLedgerField(entry.assignmentId || "", "", 140));
      return worker.workerId === target.workerId || candidateHistory.includes(targetStoryKey);
    });
    const exhaustedCandidates = candidateIds.filter((workerId) => exhaustedWorkers.has(workerId));
    const permanentCandidateIds = new Set([...selfReviewCandidates.map((worker) => worker.workerId), ...exhaustedCandidates]);
    const allCandidatesPermanentlyExcluded = candidateIds.length > 0 && candidateIds.every((workerId) => permanentCandidateIds.has(workerId));
    const readinessCandidates = (Array.isArray(warmReviewerEligibility?.candidates) ? warmReviewerEligibility.candidates : [])
      .filter((candidate) => !permanentCandidateIds.has(sanitizeLedgerField(candidate?.workerId || "", "", 80)));
    const heartbeatStale = readinessCandidates.some((candidate) => candidate.reasonCode === "warm_reviewer_heartbeat_stale");
    const readinessMissing = readinessCandidates.some((candidate) => ["warm_reviewer_readiness_not_positive", "warm_reviewer_readiness_stale"].includes(candidate.reasonCode));
    const readinessInvalid = readinessCandidates.some((candidate) => [
      "warm_reviewer_readiness_source_invalid", "warm_reviewer_readiness_mixed_observation", "warm_reviewer_readiness_future",
      "warm_reviewer_pane_ambiguous", "warm_reviewer_process_identity_mismatch", "warm_reviewer_pane_identity_mismatch",
      "warm_reviewer_session_mismatch", "warm_reviewer_owner_mismatch", "warm_reviewer_run_mismatch",
    ].includes(candidate.reasonCode));
    const scopedStateRoot = runOptions.stateRoot ? ` --state-root ${shellSingleQuote(runOptions.stateRoot)}` : "";
    const blocker = requestedSelfReview
      ? { code: "worker-code-review-self-review-excluded", message: `Requested reviewer ${requestedWorkerId} has implemented the target assignment and cannot self-review.`, nextAction: "Choose a different manager-owned reviewer." }
      : requestedWorkerId && exhaustedWorkers.has(requestedWorkerId)
        ? { code: "worker-code-review-reviewer-retries-exhausted", message: `Requested reviewer ${requestedWorkerId} exhausted the bounded delegated review retry limit.`, nextAction: "Choose a different reviewer or resolve the retained review result before retrying." }
        : requestedWorkerId && !requestedRow
          ? { code: "worker-code-review-requested-worker-unavailable", message: `Requested reviewer ${requestedWorkerId} is not eligible for this review.`, nextAction: `Refresh node ./scripts/manager-worker-progress.mjs --summary-json --run-id ${shellSingleQuote(runId)}${scopedStateRoot} before choosing another reviewer.` }
          : !requestedWorkerId && allCandidatesPermanentlyExcluded && selfReviewCandidates.length > 0
            ? { code: "worker-code-review-self-review-excluded", message: `Reviewer candidate${selfReviewCandidates.length === 1 ? "" : "s"} ${selfReviewCandidates.map((worker) => worker.workerId).join(", ")} implemented the target assignment and cannot self-review.`, nextAction: "Choose a different manager-owned reviewer." }
            : !requestedWorkerId && allCandidatesPermanentlyExcluded && exhaustedCandidates.length > 0
              ? { code: "worker-code-review-reviewer-retries-exhausted", message: `Reviewer candidate${exhaustedCandidates.length === 1 ? "" : "s"} ${exhaustedCandidates.join(", ")} exhausted the bounded delegated review retry limit.`, nextAction: "Choose a different reviewer or resolve the retained review result before retrying." }
          : heartbeatStale
            ? { code: "worker-code-review-warm-heartbeat-stale", message: "Warm reviewer pane readiness is positive, but its authoritative heartbeat is stale.", nextAction: `Refresh the manager-owned worker heartbeat under ${runOptions.stateRoot || paths.proof.state?.root || paths.root}, then rerun the read-only warm reviewer probe.` }
            : readinessInvalid
              ? { code: "worker-code-review-warm-readiness-invalid", message: "Warm reviewer readiness evidence is invalid or identity-ambiguous.", nextAction: `Repair ownership/session identity and rerun the read-only warm reviewer probe under ${runOptions.stateRoot || paths.proof.state?.root || paths.root}.` }
              : readinessMissing
                ? { code: "worker-code-review-warm-readiness-missing", message: "Warm reviewer readiness proof is absent, non-positive, or expired.", nextAction: `Run the read-only warm reviewer probe under ${runOptions.stateRoot || paths.proof.state?.root || paths.root}.` }
            : {
                code: warmReadinessHeld ? "worker-code-review-warm-readiness-held" : exhaustedWorkers.size > 0 ? "worker-code-review-reviewer-retries-exhausted" : "worker-code-review-no-reviewer",
                message: warmReadinessHeld
                  ? "Warm manager-owned worker capacity exists, but at least one reviewer readiness gate is missing, stale, or unsafe."
                  : "No manager-owned worker is available to run delegated BMAD code review without exceeding retry limits.",
                nextAction: warmReadinessHeld
                  ? `Run node ./scripts/manager-worker-prompt-probe.mjs --summary-json --run-id ${shellSingleQuote(runId)}${scopedStateRoot} --include-warm-reviewers, then rerun delegated review planning; do not warm more capacity.`
                  : "Wait for another prompt-idle manager-owned worker, warm a reviewer, or run review manually.",
              };
    return packet({
      status: "blocked",
      summary: {
        runId,
        apply: Boolean(runOptions.apply),
        mutation: "none",
        target: sanitizeCyclePacketValue({ assignmentId: targetAssignmentId, storyKey: targetStoryKey }),
        reviewAttemptSummary: sanitizeCyclePacketValue(reviewAttemptSummary),
        requests: [],
      },
      blockers: [blocker],
    });
  }

  const request = buildWorkerCodeReviewRequest({ reviewer, target, reviewPlan, paths, runOptions });
  const requestExists = existsSync(request.requestPath);
  const resultExists = existsSync(request.resultPath);
  const requestMtimeMs = fileMtimeMs(request.requestPath);
  const requestContractFresh = requestExists && fileContainsText(request.requestPath, `contractVersion: ${WORKER_CODE_REVIEW_REQUEST_VERSION}`);
  const requestFresh = requestExists && requestContractFresh && (freshness.latestInvalidatorMs === 0 || requestMtimeMs >= freshness.latestInvalidatorMs);
  const resultComplete = reviewResultHasTerminalStatus(request.resultPath);
  const resultRetentionBlocker = resultExists && reviewResultIsFail(request.resultPath)
    ? reviewFindingsRetentionBlocker(request.resultPath)
    : null;
  const resultFresh = resultExists
    && resultComplete
    && !resultRetentionBlocker
    && (freshness.latestInvalidatorMs === 0 || freshness.resultMtimeMs >= freshness.latestInvalidatorMs)
    && (!requestExists || (requestContractFresh && freshness.resultMtimeMs >= requestMtimeMs));
  const requestAgeSeconds = requestExists ? fileAgeSeconds(request.requestPath, runOptions, context) : null;
  const globalRequestAgeSeconds = freshness.requestMtimeMs > 0
    ? Math.max(0, Math.floor(((Number.isFinite(Number(runOptions.nowMs ?? context.nowMs)) ? Number(runOptions.nowMs ?? context.nowMs) : parseTimeMs(runOptions.now || context.now) || Date.now()) - freshness.requestMtimeMs) / 1000))
    : null;
  const reviewRequestCooldownSeconds = Math.max(0, nonNegativeInteger(runOptions.reviewRequestResendStaleSeconds ?? context.cyclePacket?.summary?.reviewRequestResendStaleSeconds) ?? WORKER_CODE_REVIEW_RESEND_STALE_SECONDS);
  const freshPeerRequestInFlight = !requestExists
    && freshness.requestFresh === true
    && resultFresh !== true
    && Number.isFinite(globalRequestAgeSeconds)
    && globalRequestAgeSeconds < reviewRequestCooldownSeconds;
  if (freshPeerRequestInFlight) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: Boolean(runOptions.apply),
        mutation: "none; delegated review request already in flight",
        planned: 0,
        alreadyPrepared: true,
        requestExists: false,
        requestFresh: true,
        requestContractFresh: false,
        resultExists,
        resultFresh,
        resultComplete,
        reviewFreshness: sanitizeCyclePacketValue(freshness),
        requestAgeSeconds: globalRequestAgeSeconds,
        reviewRequestCooldownSeconds,
        inFlightReviewRequest: true,
        reviewAttemptSummary: sanitizeCyclePacketValue(reviewAttemptSummary),
        results: runOptions.apply ? [{ status: "in_flight_review_request_wait" }] : undefined,
        requests: [],
        retention: "review_request_path_and_summary",
      },
      nextActions: [{
        code: "worker-code-review-request-prepared",
        summary: "A fresh delegated worker code review request is already in flight; wait for findings before rotating reviewers.",
        nextAction: "Monitor worker checkpoints for review result.",
      }],
    });
  }
  if (!runOptions.apply) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        planned: 1,
        alreadyPrepared: requestFresh,
        requestExists,
        requestFresh,
        requestContractFresh,
        resultExists,
        resultFresh,
        resultComplete,
        resultRetentionUnsafe: Boolean(resultRetentionBlocker),
        reviewFreshness: sanitizeCyclePacketValue(freshness),
        requestAgeSeconds,
        reviewAttemptSummary: sanitizeCyclePacketValue(reviewAttemptSummary),
        requests: [request],
        transport: { primary: "durable_review_request_file", secondary: "literal_safe_tmux_buffer", pastedText: "read_review_request_file_path_only" },
      },
      nextActions: [{
        code: requestFresh ? "worker-code-review-request-prepared" : "worker-code-review-apply-ready",
        summary: requestFresh
          ? resultFresh
            ? "Fresh delegated worker code review result exists; route findings or delivery next."
            : "Delegated worker code review request already exists; wait for reviewer checkpoint or findings, or resend if the prompt is visibly idle."
          : resultExists && !resultFresh
            ? resultRetentionBlocker
              ? "Delegated worker code review result is not route-safe; delegate a fresh compact review."
              : "Delegated worker code review result is stale after newer review feedback or target checkpoint; delegate a fresh review."
          : "Delegate BMAD code review to a manager-owned worker.",
        nextAction: requestFresh
          ? resultFresh
            ? `Review compact findings at ${request.resultPath}.`
            : `node ./scripts/manager-worker-code-review.mjs --summary-json --run-id ${shellSingleQuote(runId)} --assignment-id ${shellSingleQuote(targetAssignmentId)} --worker-id ${shellSingleQuote(request.workerId)} --operator-visible-prompt --apply`
          : `node ./scripts/manager-worker-code-review.mjs --summary-json --run-id ${shellSingleQuote(runId)} --assignment-id ${shellSingleQuote(targetAssignmentId)} --worker-id ${shellSingleQuote(request.workerId)} --apply`,
      }],
    });
  }

  if (requestFresh && !runOptions.operatorVisiblePrompt) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: true,
        mutation: "none; delegated review request already prepared",
        planned: 1,
        alreadyPrepared: true,
        requestExists,
        requestFresh,
        requestContractFresh,
        resultExists,
        resultFresh,
        resultComplete,
        reviewFreshness: sanitizeCyclePacketValue(freshness),
        requestAgeSeconds,
        reviewAttemptSummary: sanitizeCyclePacketValue(reviewAttemptSummary),
        results: [{ ...request, status: "already_prepared" }],
        retention: "review_request_path_and_summary",
      },
      nextActions: [{ code: "worker-code-review-request-prepared", summary: "Delegated worker code review request already exists.", nextAction: "Monitor worker checkpoints for review result." }],
    });
  }

  const reviewerRevalidation = revalidateWarmReviewerBeforeApply(reviewer, targetAssignmentId, runOptions, context);
  if (!reviewerRevalidation.ok) {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        apply: true,
        mutation: "none; warm reviewer revalidation failed before request write or paste",
        target: sanitizeCyclePacketValue({ assignmentId: targetAssignmentId, storyKey: targetStoryKey }),
        reviewer: sanitizeCyclePacketValue({ workerId: reviewer.workerId, sessionName: reviewer.sessionName, owner: reviewer.owner }),
        requests: [],
      },
      blockers: [reviewerRevalidation.blocker],
    });
  }

  let reviewReservation = null;
  let applyReviewer = reviewerRevalidation.reviewer;
  if (!reviewerRevalidation.skipped) {
    reviewReservation = reserveWorkerCodeReviewer(paths, runId, reviewerRevalidation.reviewer, request, context);
    if (!reviewReservation.ok) {
      return packet({
        ok: false,
        status: "blocked",
        summary: { runId, apply: true, mutation: "none; reviewer reservation failed before request write or paste", requests: [] },
        blockers: [{
          code: "worker-code-review-reviewer-readiness-changed",
          message: reviewReservation.error || "Warm reviewer could not be reserved immediately before paste.",
          nextAction: "Refresh authoritative worker lease and readiness evidence before retrying delegated review.",
        }],
      });
    }
    const postReservation = revalidateWarmReviewerBeforeApply(
      reviewerRevalidation.reviewer,
      targetAssignmentId,
      runOptions,
      { ...context, allowedReviewReservationId: reviewReservation.reservationId },
    );
    if (!postReservation.ok) {
      const rollback = rollbackWorkerCodeReviewReservation(paths, reviewerRevalidation.reviewer, reviewReservation.reservationId, { ...context, promotionRollback: reviewReservation.promotionRollback });
      return packet({
        ok: false,
        status: "blocked",
        summary: { runId, apply: true, mutation: "none; post-reservation readiness recheck failed before request write or paste", requests: [] },
        blockers: rollback.ok ? [postReservation.blocker] : [{ code: "worker-code-review-reservation-rollback-failed", message: rollback.error || "Reviewer reservation rollback failed after readiness changed.", nextAction: "Repair authoritative workers.json; do not dispatch review or lane work to this worker." }],
      });
    }
    applyReviewer = postReservation.reviewer;
  }

  try {
    mkdirSync(join(paths.root, "review-requests"), { recursive: true });
    mkdirSync(join(paths.root, "review-results"), { recursive: true });
    writeFileSync(request.requestPath, renderWorkerCodeReviewFile(request));
    writeFileSync(request.pastePath, `${request.pasteText}\n`);
  } catch (error) {
    const rollback = reviewReservation?.ok ? rollbackWorkerCodeReviewReservation(paths, reviewer, reviewReservation.reservationId, { ...context, promotionRollback: reviewReservation.promotionRollback }) : { ok: true };
    cleanupReviewRequestArtifacts(request);
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "none; review request write rolled back", requests: [] },
      blockers: [rollback.ok
        ? { code: "worker-code-review-request-write-failed", message: error?.message || "Review request write failed.", nextAction: "Repair manager state-root write access before retrying." }
        : { code: "worker-code-review-reservation-rollback-failed", message: rollback.error || "Reviewer reservation rollback failed after request write failure.", nextAction: "Repair authoritative workers.json; do not dispatch review or lane work to this worker." }],
    });
  }
  if (reviewReservation?.ok) {
    const finalRevalidation = revalidateWarmReviewerBeforeApply(applyReviewer, targetAssignmentId, runOptions, { ...context, allowedReviewReservationId: reviewReservation.reservationId });
    if (!finalRevalidation.ok) {
      const rollback = rollbackWorkerCodeReviewReservation(paths, reviewer, reviewReservation.reservationId, { ...context, promotionRollback: reviewReservation.promotionRollback });
      cleanupReviewRequestArtifacts(request);
      return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none; final reviewer identity recheck failed before buffer load", requests: [] }, blockers: rollback.ok ? [finalRevalidation.blocker] : [{ code: "worker-code-review-reservation-rollback-failed", message: rollback.error || "Reviewer reservation rollback failed after final identity recheck.", nextAction: "Repair authoritative workers.json; do not dispatch work to this worker." }] });
    }
    applyReviewer = finalRevalidation.reviewer;
  }
  const pasteRequest = {
    ...request,
    expectedPaneTarget: applyReviewer?.reviewerEligibility?.paneTarget || null,
    expectedCurrentCommand: applyReviewer?.reviewerEligibility?.currentCommand || null,
    ...(reviewReservation?.ok ? {
      authoritativeWorkerGuard: {
        workersPath: paths.workers,
        workerId: applyReviewer.workerId,
        owner: applyReviewer.owner,
        runId,
        sessionName: applyReviewer.sessionName,
        reservationId: reviewReservation.reservationId,
        reservationState: "reserved",
        targetAssignmentId: request.targetAssignmentId,
        paneTarget: applyReviewer?.reviewerEligibility?.paneTarget || null,
      },
    } : {}),
  };
  const paste = pasteWorkerPointer(pasteRequest, `${request.workerId}-code-review`, { ...context, requireExactSession: true });
  const result = { ...request, reservationId: reviewReservation?.reservationId || null, status: paste.ok ? (requestExists ? "code_review_request_resent" : "code_review_request_sent") : "failed", paste };
  if (!paste.ok) {
    const ambiguousDelivery = paste.deliveryMayHaveOccurred === true && reviewReservation?.ok;
    const recovery = ambiguousDelivery
      ? markWorkerReviewDeliveryRecoveryRequired(paths, reviewer, reviewReservation.reservationId, paste, context)
      : null;
    const rollback = !ambiguousDelivery && reviewReservation?.ok ? rollbackWorkerCodeReviewReservation(paths, reviewer, reviewReservation.reservationId, { ...context, promotionRollback: reviewReservation.promotionRollback }) : { ok: true };
    if (!ambiguousDelivery) cleanupReviewRequestArtifacts(request);
    recordPointerReceiptFailure(runOptions, result, context, "code-review");
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "partial", results: [result], deliveryRecovery: recovery ? sanitizeCyclePacketValue(recovery) : null },
      blockers: [ambiguousDelivery && recovery?.ok
        ? { code: "worker-code-review-delivery-ambiguous", message: paste.error || `Review pointer delivery to ${request.sessionName} may have occurred but submit/receipt proof is incomplete.`, nextAction: "Inspect the exact reviewer pane and preserved request before retrying; do not release the recovery-required reservation automatically." }
        : ambiguousDelivery
          ? { code: "worker-code-review-delivery-recovery-persistence-failed", message: recovery?.fallbackPersisted ? `Primary recovery state persistence failed; durable fallback evidence is at ${recovery.fallbackPath}.` : recovery?.error || "Ambiguous review delivery could not be persisted safely.", nextAction: recovery?.fallbackPersisted ? "Repair authoritative workers.json from the fallback evidence and inspect the exact reviewer pane before any retry." : "Repair authoritative workers.json and inspect the reviewer pane before any retry." }
          : rollback.ok
        ? { code: "worker-code-review-paste-failed", message: paste.error || `Failed to paste code review request to ${request.sessionName}.`, nextAction: "Inspect manager review request files and tmux paste result before retrying." }
        : { code: "worker-code-review-reservation-rollback-failed", message: rollback.error || "Reviewer reservation rollback failed after paste failure.", nextAction: "Repair authoritative workers.json; do not dispatch review or lane work to this worker." }],
    });
  }

  if (reviewReservation?.ok) {
    const dispatched = markWorkerReviewReservationDispatched(paths, reviewer, reviewReservation.reservationId, paste, context);
    if (!dispatched.ok) {
      return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "partial; review pointer sent but reservation persistence failed", results: [result] }, blockers: [{ code: "worker-code-review-reservation-persistence-failed", message: dispatched.error || "Reviewer reservation could not be marked dispatched after paste.", nextAction: "Hold the worker from lane dispatch and repair authoritative reservation state before recovery." }] });
    }
  }

  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_code_review_request_apply",
    authorityBasis: "manager-owned-worker-code-review-delegation-existing-gates",
    summary: `Delegated BMAD code review for ${request.targetAssignmentId} to ${request.workerId}.`,
    sourceRefs: [`assignment:${request.targetAssignmentId}`, `worker:${request.workerId}`, ...receiptSourceRefs(result)],
    evidenceRefs: [`review-request:${request.requestPath}`, `review-result:${request.resultPath}`],
    recoveryPath: "monitor delegated reviewer checkpoint and route review findings through manager-worker-review-feedback if needed",
  }, context);
  return packet({
    status: "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-code-review-request-file-and-tmux-buffer",
      results: [result],
      retention: "review_request_path_and_summary",
    },
  });
}

export function buildWorkerSubmitPendingPlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const progress = context.progressStatus || buildWorkerProgressStatus(runOptions, context);
  const pendingStates = new Set(["handoff_sent", "progress_signal_sent", "recovery_inspected", "owner_delegation_sent", "owner_delegation_stale", "pointer_receipt_unverified"]);
  const candidates = Array.isArray(progress.summary?.workerProgress)
    ? filterWorkersByExactTarget(progress.summary.workerProgress, runOptions)
      .filter((worker) => runOptions.operatorVisiblePrompt || pendingStates.has(worker.progressState))
      .filter((worker) => runOptions.operatorVisiblePrompt || worker.progressState !== "handoff_sent" || worker.submitPendingAfterHandoff !== true)
      .filter((worker) => runOptions.operatorVisiblePrompt || Number(worker.checkpointCount || 0) === 0 || needsPendingSubmitRepair(worker))
      .filter((worker) => Number(worker.questionCount || 0) === 0)
    : [];
  const limit = runOptions.limit === null || runOptions.limit === undefined ? candidates.length : Math.max(0, Number(runOptions.limit) || 0);
  const selected = candidates.slice(0, limit).map((worker) => ({
    workerId: sanitizeLedgerField(worker.workerId || "", "", 80),
    sessionName: sanitizeLedgerField(worker.sessionName || worker.workerId || "", "", 80),
    assignmentId: sanitizeLedgerField(worker.assignmentId || "", "", 140),
    taskId: sanitizeLedgerField(worker.taskId || "", "", 140),
    progressState: sanitizeLedgerField(worker.progressState || "unknown", "unknown", 80),
    action: "send_enter_only_to_active_tmux_pane",
    basis: runOptions.operatorVisiblePrompt ? "operator_visible_prompt" : "metadata_pending_prompt",
  }));
  if (selected.length === 0) {
    return packet({
      status: "ready",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", pendingWorkers: candidates.length, requests: [] },
      nextActions: [{ code: "worker-submit-pending-not-needed", summary: "No pending manager-owned worker prompt submit is needed.", nextAction: "Continue metadata-only monitoring." }],
    });
  }
  if (!runOptions.apply) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        pendingWorkers: candidates.length,
        planned: selected.length,
        requests: selected,
        continuousSelection: buildContinuousSelectionProof({
          code: "continuous-worker-submit-pending",
          mutationClass: "manager_owned_worker_enter_only",
          runId,
          targets: selected,
        }),
        transport: {
          primary: "tmux_send_c_m_only",
          pastedText: "none",
          submitKey: "C-m",
          basis: runOptions.operatorVisiblePrompt ? "operator_visible_prompt" : "metadata_pending_prompt",
        },
      },
      nextActions: [{ code: "worker-submit-pending-apply-ready", summary: `Submit pending prompts for ${selected.length} manager-owned worker(s).`, nextAction: `node ./scripts/manager-worker-submit-pending.mjs --summary-json --limit ${selected.length}${runOptions.operatorVisiblePrompt ? " --operator-visible-prompt" : ""} --apply` }],
    });
  }
  const runner = context.tmuxRunner || spawnSync;
  const results = selected.map((request) => {
    const submit = sendTmuxEnterToSession(request.sessionName, runner, context);
    if (!submit.ok) return { ...request, status: "failed", submit };
    const receipt = verifyTmuxEnterOnlySubmitted(request, submit, runner, context);
    return { ...request, status: receipt.verified === false ? "receipt_unverified" : "submitted", submit, receipt };
  });
  const failed = results.find((result) => result.status === "failed");
  if (failed) {
    recordPointerReceiptFailure(runOptions, failed, context, "owner-delegation");
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "partial", results },
      blockers: [{ code: "worker-submit-pending-failed", message: failed.submit?.error || `Failed to submit C-m to ${failed.sessionName}.`, nextAction: "Refresh worker progress and retry only if the prompt is still pending." }],
    });
  }
  const unverified = results.filter((result) => result.status === "receipt_unverified");
  if (unverified.length > 0) {
    for (const result of unverified) {
      recordPointerReceiptFailure(runOptions, result, context, "submit-pending");
    }
    return packet({
      status: "attention",
      summary: {
        runId,
        apply: true,
        mutation: "manager-owned-worker-enter-only-submit-receipt-unverified",
        results,
        retention: "submit_path_and_bounded_receipt_summary",
      },
      warnings: [{
        code: "worker-submit-pending-receipt-unverified",
        message: `${unverified.length} submit-pending repair(s) still show manager pointer text after C-m.`,
        nextAction: "Rerun manager-worker-progress and route through recovery before sending more worker text.",
      }],
      nextActions: [{
        code: "worker-submit-pending-receipt-unverified",
        summary: "Submit-pending C-m was sent, but bounded receipt proof is still unverified.",
        nextAction: "Run node ./scripts/manager-worker-progress.mjs --summary-json before any further worker mutation.",
      }],
    });
  }
  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_submit_pending_apply",
    authorityBasis: "manager-owned-worker-enter-only-repair-existing-gates",
    summary: `Submitted pending prompt(s) for ${results.length} manager-owned worker(s).`,
    sourceRefs: results.flatMap((result) => [`assignment:${result.assignmentId}`, `worker:${result.workerId}`]),
    evidenceRefs: results.map((result) => `submit-pending:${result.workerId || result.assignmentId}`),
    recoveryPath: "rerun manager-worker-progress and inspect compact checkpoints before retrying",
    recordPolicy: runOptions.operatorVisiblePrompt ? "operator_visible_enter_only_repair" : "",
  }, context);
  return packet({
    status: "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-enter-only-submit",
      results,
      retention: "submit_path_and_summary",
    },
  });
}

export function buildWorkerPromptProbePlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const workerPacket = context.workerStatus || buildWorkerStatus(runOptions, context);
  const workers = Array.isArray(workerPacket.summary?.workers)
    ? workerPacket.summary.workers.filter(isPlainObject).map(projectWorker)
    : [];
  const missingLiveWorkerIds = missingLiveWorkerIdsFromWorkerStatus(workerPacket);
  const includeWarmReviewers = runOptions.includeWarmReviewers === true || context.includeWarmReviewers === true;
  const candidateProbeWorkers = workers
    .filter((worker) => (
      isManagerOwnedWorker(worker, runId) &&
      !isManagerControlPlaneWorker(worker, runId) &&
      (!missingLiveWorkerIds.has(worker.workerId) || (includeWarmReviewers && typeof context.tmuxRunner === "function")) &&
      (worker.state === "active" || (includeWarmReviewers && isWarmReviewerCapacityRecord(worker)))
    ))
    .filter((worker) => !runOptions.workerId || worker.workerId === runOptions.workerId);
  const excludedCandidates = includeWarmReviewers
    ? candidateProbeWorkers
        .map((worker) => ({ worker, reasonCode: warmReviewerPreCaptureExclusionReason(worker, { allowBootingRecoveryProbe: true }) }))
        .filter((row) => row.reasonCode)
        .map((row) => ({ workerId: row.worker.workerId, sessionName: row.worker.sessionName, reasonCode: row.reasonCode, rawPayloadRetained: false }))
    : [];
  const excludedWorkerIds = new Set(excludedCandidates.map((row) => row.workerId));
  const probeWorkers = candidateProbeWorkers.filter((worker) => !excludedWorkerIds.has(worker.workerId));
  const runner = context.tmuxRunner || spawnSync;
  const probes = probeWorkers.map((worker) => probeWorkerInputRegion(worker, runner, { ...context, receiptScanLines: 10, now: context.now || runOptions.now }));
  const stuck = probes.filter((probe) => probe.inputHasManagerPointer);
  const limit = runOptions.limit === null || runOptions.limit === undefined ? stuck.length : Math.max(0, Number(runOptions.limit) || 0);
  const selected = stuck.slice(0, limit);
  if (includeWarmReviewers && runOptions.apply) {
    return packet({
      status: stuck.length > 0 ? "attention" : "ready",
      summary: {
        runId,
        apply: true,
        mutation: "none; warm reviewer readiness probe is read-only",
        probedWorkers: probes.length,
        warmReviewerProbe: true,
        promptPointerWorkers: stuck.length,
        probes,
        excludedCandidates,
        retention: "metadata_only_prompt_region_probe",
      },
      warnings: stuck.length > 0
        ? [{ code: "worker-warm-reviewer-pointer-visible", message: `${stuck.length} warm reviewer probe(s) show pending input; readiness remains held and no pane input was sent.` }]
        : [],
      nextActions: [{
        code: stuck.length > 0 ? "worker-warm-reviewer-readiness-held" : "worker-warm-reviewer-probe-clear",
        summary: stuck.length > 0 ? "Warm reviewer readiness is held without mutating the pane." : "Warm reviewer readiness probe completed without mutation.",
        nextAction: stuck.length > 0 ? "Use the separate bounded worker repair gate before probing reviewer readiness again." : "Continue metadata-only monitoring.",
      }],
    });
  }
  if (selected.length === 0) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: Boolean(runOptions.apply),
        mutation: "none",
        probedWorkers: probes.length,
        warmReviewerProbe: includeWarmReviewers,
        promptPointerWorkers: 0,
        probes,
        excludedCandidates,
        retention: "metadata_only_prompt_region_probe",
      },
      nextActions: [{ code: "worker-prompt-probe-clear", summary: "No manager pointer text is visible in worker input regions.", nextAction: "Continue metadata-only monitoring." }],
    });
  }
  if (!runOptions.apply) {
    return packet({
      status: "attention",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        probedWorkers: probes.length,
        warmReviewerProbe: includeWarmReviewers,
        promptPointerWorkers: stuck.length,
        planned: selected.length,
        probes,
        excludedCandidates,
        requests: selected.map(promptProbeRequestSummary),
        continuousSelection: buildContinuousSelectionProof({
          code: "continuous-worker-prompt-probe",
          mutationClass: "manager_owned_worker_enter_only_prompt_region_probe",
          runId,
          targets: selected.map(promptProbeRequestSummary),
        }),
        transport: { primary: "tmux_send_c_m_only", pastedText: "none", submitKey: "C-m", basis: "bounded_prompt_region_probe" },
        retention: "metadata_only_prompt_region_probe",
      },
      warnings: [{ code: "worker-prompt-pointer-visible", message: `${stuck.length} manager-owned worker input region(s) contain manager pointer text.` }],
      nextActions: [{ code: "worker-prompt-probe-submit-ready", summary: `Submit visible manager pointers for ${selected.length} worker input region(s).`, nextAction: `node ./scripts/manager-worker-prompt-probe.mjs --summary-json${includeWarmReviewers ? " --include-warm-reviewers" : ""}${workerExactTargetFlags(selected[0]) || ` --limit ${selected.length}`} --apply` }],
    });
  }
  const results = selected.map((probe) => {
    const submit = sendTmuxEnterToTarget(probe.paneTarget, runner, context);
    waitForReceiptSettle(runner, context);
    const after = probeWorkerInputRegion(probe, runner, { ...context, receiptScanLines: 10 });
    return {
      ...promptProbeRequestSummary(probe),
      status: submit.ok && after.inputHasManagerPointer !== true ? "submitted_and_cleared" : submit.ok ? "submitted_still_visible" : "failed",
      submit,
      verifiedClear: submit.ok && after.inputHasManagerPointer !== true,
      after: {
        promptDetected: after.promptDetected,
        inputHasManagerPointer: after.inputHasManagerPointer,
      },
    };
  });
  const failed = results.filter((result) => result.status === "failed");
  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_prompt_region_submit_apply",
    authorityBasis: "manager-owned-worker-enter-only-repair-existing-gates",
    summary: `Submitted visible manager pointer prompt(s) for ${results.length} manager-owned worker(s).`,
    sourceRefs: results.flatMap((result) => [`assignment:${result.assignmentId}`, `worker:${result.workerId}`, result.verifiedClear ? "prompt-region:cleared" : "prompt-region:still-visible"]),
    evidenceRefs: results.map((result) => `prompt-probe:${result.workerId || result.assignmentId}`),
    recoveryPath: "rerun manager-worker-prompt-probe and inspect compact worker checkpoints before retrying",
    recordPolicy: "metadata_only_prompt_region_probe",
  }, context);
  return packet({
    ok: failed.length === 0,
    status: failed.length > 0 ? "attention" : "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-enter-only-submit",
      probedWorkers: probes.length,
      warmReviewerProbe: includeWarmReviewers,
      promptPointerWorkers: stuck.length,
      results,
      continuousSelection: buildContinuousSelectionProof({
        code: "continuous-worker-prompt-probe",
        mutationClass: "manager_owned_worker_enter_only_prompt_region_probe",
        runId,
        targets: results,
      }),
      retention: "metadata_only_prompt_region_probe",
    },
    warnings: results.some((result) => result.verifiedClear !== true)
      ? [{ code: "worker-prompt-pointer-still-visible", message: "At least one manager pointer remained visible after C-m-only submit; continue bounded prompt-region probing." }]
      : [],
  });
}

function bootingWarmReviewerRetireExclusionReason(worker = {}, runId = "", exactTarget = {}) {
  if (!worker || !worker.workerId) return "worker_missing";
  if (!isManagerOwnedWorker(worker, runId)) return "owner_or_run_mismatch";
  if (isManagerControlPlaneWorker(worker, runId)) return "manager_control_plane_excluded";
  if (!worker.sessionName) return "session_missing";
  if (exactTarget.workerId && worker.workerId !== exactTarget.workerId) return "worker_mismatch";
  if (exactTarget.sessionName && worker.sessionName !== exactTarget.sessionName) return "session_mismatch";
  if (worker.state !== "warm" || worker.recoveryState !== "restarted_booting") return "not_booting_warm_reviewer";
  if (workerHasTakeoverAmbiguity(worker)) return "takeover_or_owner_ambiguous";
  if (worker.busy === true) return "worker_busy";
  if (worker.assignmentId || worker.taskId || worker.leaseId || worker.currentLease?.assignmentId || worker.currentLease?.taskId || worker.currentLease?.leaseId || hasActiveWorkerLease(worker)) return "assignment_task_or_lease_present";
  if (isPlainObject(worker.reviewReservation) || workerHasPendingRequest(worker)) return "reservation_or_request_present";
  return "";
}

function inspectBootingWarmReviewerRetireCandidate(worker = {}, runId = "", exactTarget = {}, context = {}) {
  const exclusion = bootingWarmReviewerRetireExclusionReason(worker, runId, exactTarget);
  if (exclusion) return { eligible: false, code: "worker-retire-no-candidates", reason: exclusion };
  const sampledAt = new Date().toISOString();
  const sampledNowMs = Date.parse(sampledAt);
  const bootedMs = parseTimeMs(worker.bootStartedAt || worker.lastHeartbeatAt || "");
  if (!bootedMs || sampledNowMs - bootedMs < BOOTING_WARM_REVIEWER_RETIRE_GRACE_MS) {
    return { eligible: false, code: "worker-retire-booting-grace-active", reason: "boot_grace_not_elapsed", sampledAt };
  }
  const probe = probeWorkerInputRegion(
    { ...worker, paneTarget: null, paneId: null },
    context.tmuxRunner || spawnSync,
    { ...context, now: sampledAt, requireExactSession: true, requireSinglePane: true },
  );
  const identityReady = probe.captureOk === true && probe.singlePane === true && probe.paneCount === 1 &&
    probe.sessionName === worker.sessionName && probe.resolvedSessionName === worker.sessionName &&
    probe.owner === worker.owner && probe.runId === runId && probe.currentCommand === "codex" && probe.paneTarget && probe.paneId === probe.paneTarget;
  if (!identityReady) {
    return { eligible: false, code: "worker-retire-booting-readiness-ambiguous", reason: probe.error || "exact owner/run/session/pane Codex identity or capture proof missing", sampledAt, probe: promptProbeRequestSummary(probe) };
  }
  if (probe.promptIdle === true && probe.emptyInput === true && probe.inputPending !== true) {
    return { eligible: false, code: "worker-retire-booting-target-promotable", reason: "positive readiness proof requires promotion/review routing", sampledAt, probe: promptProbeRequestSummary(probe) };
  }
  if (probe.inputPending === true || probe.inputHasManagerPointer === true || probe.promptDetected === true) {
    return { eligible: false, code: "worker-retire-booting-input-pending", reason: "prompt input or manager pointer remains visible", sampledAt, probe: promptProbeRequestSummary(probe) };
  }
  return { eligible: true, code: "worker-retire-booting-negative-readiness", reason: "fresh exact identity-bound non-ready observation after boot grace", sampledAt, paneTarget: probe.paneTarget, probe: promptProbeRequestSummary(probe) };
}

function reconcileExactSessionAfterKill(sessionName = "", runner = spawnSync, context = {}) {
  const target = `=${sessionName}`;
  const result = runner("tmux", ["has-session", "-t", target], { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
  if (result?.error || result?.status === null || result?.status === undefined) {
    return { status: "ambiguous", target, error: result?.error?.message || "exact session reconciliation did not return a status" };
  }
  if (result.status === 0) return { status: "live", target };
  const detail = String(result.stderr || result.stdout || "").trim();
  if (result.status === 1 && /(?:can't find|cannot find|no such|not found).*session|session.*(?:can't find|cannot find|no such|not found)/i.test(detail)) {
    return { status: "missing", target, evidence: sanitizeLedgerField(detail, "exact session missing", 240) };
  }
  return { status: "ambiguous", target, error: String(result.stderr || result.stdout || `tmux has-session exited ${result.status}`).trim(), exitStatus: result.status };
}

function workerRetireResultIsFinal(result = {}) {
  return ["retired", "retired_reconciled"].includes(result.status);
}

export function buildWorkerRetirePlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  const resourceState = normalizePosture(runOptions.resourceState || context.resourceState || context.resourceContext, "unknown");
  const resourceContext = context.resourceContext || (resourceState !== "unknown" ? { status: resourceState } : undefined);
  const progress = resourceState === "critical" ? null : context.progressStatus || buildWorkerProgressStatus(runOptions, context);
  const workerPacket = context.workerStatus || buildWorkerStatus(runOptions, { ...context, resourceContext });
  const workers = Array.isArray(workerPacket.summary?.workers) ? workerPacket.summary.workers.filter(isPlainObject).map(projectWorker) : [];
  const workersById = new Map(workers.map((worker) => [worker.workerId, worker]));
  const questionAnswer = resourceState === "critical" || !runOptions.retireBlockedQuestion
    ? null
    : context.questionAnswerPlan || buildWorkerQuestionAnswerPlan(runOptions, { ...context, workerStatus: workerPacket, progressStatus: progress });
  const criticalKillOrder = Array.isArray(workerPacket.summary?.lifecyclePlan?.terminationPlan?.killOrder)
    ? workerPacket.summary.lifecyclePlan.terminationPlan.killOrder
    : [];
  const progressWorkers = Array.isArray(progress?.summary?.workerProgress) ? progress.summary.workerProgress : [];
  const recoverySubmitCandidates = progressWorkers
    .filter((worker) => worker.progressState === "recovery_submit_unanswered")
    .filter((worker) => workerMatchesExactTarget(worker, runOptions))
    .map((worker) => ({ ...worker, retireBasis: "recovery_submit_unanswered", record: workersById.get(worker.workerId) || null }))
    .filter((worker) => worker.record && isManagerOwnedWorker(worker.record, runId) && worker.record.state === "active" && worker.record.sessionName);
  const exactBootingRecoveryRequested = Boolean(runOptions.workerId && runOptions.sessionName && !runOptions.assignmentId && !runOptions.taskId);
  const exactBootingWorker = exactBootingRecoveryRequested ? workers.find((worker) => workerMatchesExactTarget(worker, runOptions)) : null;
  const bootingRetireInspection = exactBootingWorker
    ? inspectBootingWarmReviewerRetireCandidate(exactBootingWorker, runId, runOptions, context)
    : null;
  const bootingRecoveryCandidates = exactBootingRecoveryRequested
    ? workers
        .filter((worker) => workerMatchesExactTarget(worker, runOptions))
        .filter(() => bootingRetireInspection?.eligible === true)
        .map((worker) => ({
          ...worker,
          progressState: "restarted_booting",
          retireBasis: "booting_warm_reviewer_recovery",
          record: worker,
        }))
    : [];
  const blockedQuestionCandidates = runOptions.retireBlockedQuestion
    ? buildBlockedQuestionRetireCandidates({ progressWorkers, questionAnswer, workersById, runOptions, runId })
    : [];
  const missingLiveSessionIds = missingLiveWorkerIdsFromWorkerStatus(workerPacket);
  const missingSessionCandidates = runOptions.retireMissingSession
    ? workers
      .filter((worker) => workerMatchesExactTarget(worker, runOptions))
      .filter((worker) => missingLiveSessionIds.has(worker.workerId))
      .filter((worker) => (
        worker.state === "warm" &&
        !worker.assignmentId &&
        !worker.taskId &&
        !worker.leaseId &&
        !worker.currentLease?.assignmentId &&
        !hasActiveWorkerLease(worker)
      ))
      .map((worker) => ({
        ...worker,
        progressState: "missing_live_tmux_session",
        retireBasis: "missing_live_tmux_session",
        record: worker,
      }))
      .filter((worker) => isManagerOwnedWorker(worker.record, runId) && worker.record.sessionName)
    : [];
  const candidates = resourceState === "critical"
    ? criticalKillOrder
      .map((worker) => ({ ...worker, progressState: "critical_resource_pressure", retireBasis: "critical_resource_pressure", record: workersById.get(worker.workerId) || null }))
      .filter((worker) => workerMatchesExactTarget({ ...worker.record, ...worker }, runOptions))
      .filter((worker) => worker.record && isManagerOwnedWorker(worker.record, runId) && worker.record.sessionName)
    : runOptions.retireBlockedQuestion
      ? blockedQuestionCandidates
      : runOptions.retireMissingSession
        ? missingSessionCandidates
      : exactBootingRecoveryRequested
        ? bootingRecoveryCandidates
        : recoverySubmitCandidates;
  const limit = exactTargetLimit(runOptions, runOptions.limit === null || runOptions.limit === undefined ? candidates.length : Math.max(0, Number(runOptions.limit) || 0));
  const selected = candidates.slice(0, Math.max(0, Math.min(6, limit))).map((worker) => ({
    workerId: sanitizeLedgerField(worker.workerId || "", "", 80),
    sessionName: sanitizeLedgerField(worker.sessionName || worker.record?.sessionName || "", "", 80),
    assignmentId: sanitizeLedgerField(worker.assignmentId || worker.record?.assignmentId || "", "", 140),
    taskId: sanitizeLedgerField(worker.taskId || worker.record?.taskId || "", "", 140),
    leaseId: sanitizeLedgerField(worker.leaseId || worker.record?.leaseId || worker.record?.currentLease?.leaseId || "", "", 140) || null,
    leaseState: sanitizeLedgerField(worker.leaseState?.state || worker.leaseState || worker.record?.leaseState || worker.record?.currentLease?.state || "", "", 80) || null,
    progressState: sanitizeLedgerField(worker.progressState || "unknown", "unknown", 80),
    action: "retire_manager_owned_worker_session",
    basis: sanitizeLedgerField(resourceState === "critical" ? "critical_resource_pressure" : worker.retireBasis || "recovery_submit_unanswered", "recovery_submit_unanswered", 100),
    resourceSnapshot: resourceState === "critical" ? worker.resourceSnapshot || workerPacket.summary?.lifecyclePlan?.terminationPlan?.resourceSnapshot || null : null,
    affectedLease: resourceState === "critical" ? worker.affectedLease || buildTerminationAffectedLease(worker.record || worker) : null,
    recoveryAction: resourceState === "critical"
      ? "mark_lease_recovery_required_before_work_resumes"
      : worker.retireBasis === "unsafe_question_policy_blocked"
        ? "park_policy_blocked_lane_and_free_worker_capacity"
        : worker.retireBasis === "booting_warm_reviewer_recovery"
          ? "retire_unready_booting_warm_reviewer"
        : worker.retireBasis === "missing_live_tmux_session"
          ? "retire_logical_record_after_verified_missing_live_session"
        : "retire_recovery_stuck_worker",
    retireMarker: worker.retireBasis === "unsafe_question_policy_blocked" ? RETIRE_BLOCKED_QUESTION_BASIS : null,
    blockedQuestion: worker.blockedQuestion || null,
  }));
  const blockers = [];
  if (!paths.proof.ok) {
    blockers.push({ code: "workspace-state-unsafe", message: paths.proof.error, nextAction: "Choose a safe workspace state root." });
  }
  if (runOptions.retireMissingSession && !runOptions.workerId) {
    blockers.push({
      code: "worker-retire-missing-session-requires-exact-target",
      message: "Missing-session logical retirement requires an exact worker-id target.",
      nextAction: "Provide --worker-id for one manager-owned warm record after verifying its session is absent and it has no assignment or lease.",
    });
  }
  if (runOptions.retireMissingSession && runOptions.retireBlockedQuestion) {
    blockers.push({
      code: "worker-retire-conflicting-modes",
      message: "Missing-session and blocked-question retirement modes cannot be combined.",
      nextAction: "Run one exact retirement mode at a time.",
    });
  }
  if (selected.length === 0) {
    blockers.push({
      code: resourceState === "critical" ? "worker-retire-no-critical-resource-candidates" : bootingRetireInspection?.code || "worker-retire-no-candidates",
      message: resourceState === "critical"
        ? "No manager-owned worker is eligible for critical resource termination."
        : runOptions.retireBlockedQuestion
          ? "No manager-owned unsafe-question-blocked worker is eligible for retire."
          : runOptions.retireMissingSession
            ? "No exact-target manager-owned warm worker with verified missing live session and no assignment or lease is eligible for logical retirement."
          : exactBootingRecoveryRequested
            ? "No exact-target manager-owned booting warm reviewer is safely eligible for retire."
            : "No manager-owned recovery-submit-unanswered worker is eligible for retire.",
      nextAction: resourceState === "critical"
        ? "Refresh manager-resource-status and worker-status before retrying critical resource termination."
        : bootingRetireInspection?.code === "worker-retire-booting-target-promotable"
          ? "Run the bounded warm-reviewer readiness/review dry-run and promote through the existing review apply gate; do not retire this worker."
          : "Refresh manager-worker-progress and exact booting readiness evidence before retrying retire.",
    });
  }
  if (blockers.length > 0) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", candidates: candidates.length, planned: selected.length, requests: selected },
      blockers,
    });
  }
  if (!runOptions.apply) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        candidates: candidates.length,
        planned: selected.length,
        resourceState,
        requests: selected,
        continuousSelection: buildContinuousSelectionProof({
          code: "continuous-worker-retire",
          mutationClass: "manager_owned_worker_retire",
          runId,
          targets: selected,
        }),
        stopLines: ["manager-owned-session-only", "no unknown session mutation", "no assignment takeover", "no dispatch apply", "no provider payload retention", ...(runOptions.retireMissingSession ? ["missing-session-logical-retirement-only", "do-not-kill-absent-session"] : [])],
      },
      nextActions: [{
        code: "worker-retire-apply-ready",
        summary: workerRetireSummary(resourceState, selected),
        nextAction: `node ./scripts/manager-worker-retire.mjs --summary-json${workerExactTargetFlags(selected[0]) || ` --limit ${selected.length}`}${resourceState === "critical" ? " --resource-state critical" : ""}${selected.some((request) => request.basis === "unsafe_question_policy_blocked") ? " --retire-blocked-question" : ""}${selected.some((request) => request.basis === "missing_live_tmux_session") ? " --retire-missing-session" : ""} --apply`,
      }],
    });
  }
  return withWorkerAssignmentLock(paths, context, () => {
  writeJsonIfMissing(paths.workers, []);
  const workerRead = readJsonArray(paths.workers);
  if (workerRead.warning) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "none" },
      blockers: [{ code: workerRead.warning.code, message: workerRead.warning.message, nextAction: "Repair manager workers.json before retiring workers." }],
    });
  }
  const runner = context.tmuxRunner || spawnSync;
  const workerRecords = workerRead.value.filter(isPlainObject).map(projectWorker);
  const results = [];
  for (const request of selected) {
    const record = workerRecords.find((worker) => worker.workerId === request.workerId && isManagerOwnedWorker(worker, runId));
    const bootingRecoveryExclusion = request.basis === "booting_warm_reviewer_recovery"
      ? bootingWarmReviewerRetireExclusionReason(record, runId, request)
      : "";
    if (bootingRecoveryExclusion) {
      return packet({
        ok: false,
        status: "blocked",
        summary: { runId, apply: true, mutation: "none", results },
        blockers: [{ code: "worker-retire-booting-target-changed", message: `Exact-target booting worker is no longer safe to retire: ${bootingRecoveryExclusion}.`, nextAction: "Refresh worker status and rerun exact-target retirement preview; do not kill the session." }],
      });
    }
    const missingSessionLogical = request.basis === "missing_live_tmux_session";
    const expectedState = request.basis === "booting_warm_reviewer_recovery" || missingSessionLogical ? "warm" : "active";
    if (!record || !record.sessionName || (resourceState !== "critical" && record.state !== expectedState)) {
      results.push({ ...request, status: "skipped_not_active_manager_owned" });
      continue;
    }
    if (missingSessionLogical && (
      record.assignmentId ||
      record.taskId ||
      record.leaseId ||
      record.currentLease?.assignmentId ||
      hasActiveWorkerLease(record)
    )) {
      return packet({
        ok: false,
        status: "blocked",
        summary: { runId, apply: true, mutation: "none", results },
        blockers: [{ code: "worker-retire-missing-session-worker-gained-work", message: "The exact missing-session worker gained an assignment or lease before logical retirement.", nextAction: "Refresh worker status and do not retire this worker." }],
      });
    }
    if (request.basis === "booting_warm_reviewer_recovery") {
      const reinspection = inspectBootingWarmReviewerRetireCandidate(record, runId, request, { ...context, tmuxRunner: runner });
      if (!reinspection.eligible) {
        return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none", results }, blockers: [{ code: reinspection.code, message: `Exact-target booting worker cannot be retired: ${reinspection.reason}.`, nextAction: reinspection.code === "worker-retire-booting-target-promotable" ? "Promote through bounded review apply; do not kill the session." : "Refresh exact live pane readiness and retry only after an identity-bound negative observation." }] });
      }
      const finalInspection = inspectBootingWarmReviewerRetireCandidate(record, runId, request, { ...context, tmuxRunner: runner });
      if (!finalInspection.eligible || finalInspection.paneTarget !== reinspection.paneTarget) {
        return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none", results }, blockers: [{ code: "worker-retire-booting-target-changed", message: "Exact booting session/pane/readiness changed immediately before kill.", nextAction: "Refresh exact live pane readiness; do not kill the session." }] });
      }
      record.lifecycleState = "retiring_physical";
      record.recoveryState = "retiring_physical";
      record.recoveryAction = "reconcile_exact_session_retirement_before_retry";
      record.retirementRequest = `exact_session:${record.sessionName}`;
      try {
        writeWorkerRecordsAtomically(paths, workerRecords, context, "retire_pre_kill");
      } catch (error) {
        return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none", results }, blockers: [{ code: "worker-retire-pre-kill-persistence-failed", message: error?.message || "Could not persist retiring_physical before kill.", nextAction: "Repair workers.json persistence; the exact session was not killed." }] });
      }
      const preKillIdentity = resolveTmuxPaneTarget(record.sessionName, runner, { ...context, requireExactSession: true, requireSinglePane: true });
      const preKillIdentityReady = preKillIdentity.ok === true && preKillIdentity.sessionName === record.sessionName &&
        preKillIdentity.currentCommand === "codex" && preKillIdentity.target === finalInspection.paneTarget;
      if (!preKillIdentityReady) {
        record.lifecycleState = "retirement_blocked";
        record.recoveryState = "retire_pre_kill_recovery_required";
        record.recoveryAction = "refresh_exact_session_identity_before_retirement";
        try {
          writeWorkerRecordsAtomically(paths, workerRecords, context, "retire_pre_kill_identity_changed");
        } catch (error) {
          return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none; durable retiring_physical marker preserved", results }, blockers: [{ code: "worker-retire-pre-kill-identity-persistence-failed", message: error?.message || "Pre-kill identity change could not be persisted.", nextAction: "Use the durable retiring_physical marker to inspect the exact session; do not kill it." }] });
        }
        return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "none; durable pre-kill recovery marker", results }, blockers: [{ code: "worker-retire-pre-kill-identity-changed", message: preKillIdentity.error || "Exact session, single-pane Codex process, or pane identity changed after retiring_physical persistence.", nextAction: record.recoveryAction }] });
      }
    }
    const retiredAt = new Date().toISOString();
    let kill = null;
    let killOk = false;
    let killReconciliation = null;
    if (missingSessionLogical) {
      killReconciliation = reconcileExactSessionAfterKill(record.sessionName, runner, context);
      if (killReconciliation.status !== "missing") {
        return packet({
          ok: false,
          status: "blocked",
          summary: { runId, apply: true, mutation: "none", results },
          blockers: [{ code: "worker-retire-missing-session-live-or-ambiguous", message: `Exact worker session is ${killReconciliation.status}; logical retirement did not mutate it.`, nextAction: "Refresh exact tmux session identity and keep the worker blocked until absence is proven." }],
        });
      }
      killOk = true;
    } else {
      const killTarget = request.basis === "booting_warm_reviewer_recovery" ? `=${record.sessionName}` : record.sessionName;
      kill = runner("tmux", ["kill-session", "-t", killTarget], { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
      killOk = !kill?.error && (kill?.status ?? 0) === 0;
    }
    if (!killOk && request.basis === "booting_warm_reviewer_recovery") {
      killReconciliation = reconcileExactSessionAfterKill(record.sessionName, runner, context);
      if (killReconciliation.status === "missing") {
        killOk = true;
      } else {
        record.lifecycleState = "retirement_blocked";
        record.recoveryState = "retire_kill_recovery_required";
        record.recoveryAction = killReconciliation.status === "live"
          ? "inspect_exact_live_session_before_retrying_retirement"
          : "reconcile_ambiguous_exact_session_kill_outcome";
        try {
          writeWorkerRecordsAtomically(paths, workerRecords, context, "retire_kill_recovery_required");
        } catch (error) {
          return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "partial; durable retiring_physical marker preserved", results }, blockers: [{ code: "worker-retire-kill-recovery-persistence-failed", message: error?.message || "Could not persist reconciled kill recovery state.", nextAction: "Use the durable retiring_physical marker to inspect the exact session before any retry." }] });
        }
        results.push({ ...request, status: "retirement_recovery_required", sessionName: record.sessionName, kill: { ok: false, error: kill?.error?.message || String(kill?.stderr || kill?.stdout || "tmux kill-session failed").trim(), status: kill?.status }, reconciliation: killReconciliation });
        return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "partial; durable retirement recovery marker", results }, blockers: [{ code: "worker-retire-kill-recovery-required", message: `Exact session kill outcome requires recovery: ${killReconciliation.status}.`, nextAction: record.recoveryAction }] });
      }
    }
    results.push({ ...request, status: killOk ? (killReconciliation?.status === "missing" ? "retired_reconciled" : "retired") : "failed", sessionName: record.sessionName, kill: killOk ? { ok: true, sessionName: record.sessionName, skipped: missingSessionLogical, reason: missingSessionLogical ? "session_already_missing" : undefined, reconciled: killReconciliation?.status === "missing" } : { ok: false, error: kill?.error?.message || String(kill?.stderr || kill?.stdout || "tmux kill-session failed").trim(), status: kill?.status }, ...(killReconciliation ? { reconciliation: killReconciliation } : {}) });
    if (!killOk) {
      const retiredCount = results.filter(workerRetireResultIsFinal).length;
      if (retiredCount > 0) {
        writeFileSync(paths.workers, `${JSON.stringify(workerRecords, null, 2)}\n`);
        const finalRetiredResults = results.filter(workerRetireResultIsFinal);
        ledgerCommand({
          command: "append-event",
          runId,
          stateRoot: runOptions.stateRoot,
          eventType: "worker_retire_apply",
          authorityBasis: workerRetireAuthorityBasis(resourceState, results),
          summary: `Partially ${lowercaseFirst(workerRetirePastTenseSummary(resourceState, finalRetiredResults))} before a later failure.`,
          sourceRefs: finalRetiredResults.map((result) => `assignment:${result.assignmentId}`),
          evidenceRefs: finalRetiredResults.map((result) => `worker-retire:${result.workerId || result.assignmentId}`),
          recoveryPath: resourceState === "critical" ? "refresh worker status and reconcile recovery-required leases before resuming work" : "warm a replacement manager-owned worker and hand off the next source-owned lane through existing gates",
          recordPolicy: resourceState === "critical" ? "metadata_only_critical_resource_worker_retire_partial" : "metadata_only_worker_retire_partial",
        }, context);
      }
      return packet({
        ok: false,
        status: "blocked",
        summary: { runId, apply: true, mutation: "partial", results },
        blockers: [{ code: "worker-retire-kill-failed", message: results.at(-1).kill.error || `Failed to retire ${record.sessionName}.`, nextAction: "Inspect tmux session state and retry only if the worker remains manager-owned and stuck." }],
      });
    }
    record.state = "retired";
    record.lastHeartbeatAt = retiredAt;
    record.failureCount = Number(record.failureCount || 0) + 1;
    if (resourceState === "critical" && (record.assignmentId || record.currentLease?.assignmentId)) {
      record.assignmentState = "recovery_required";
      record.leaseState = "recovery_required";
      if (record.currentLease) record.currentLease = { ...record.currentLease, state: "recovery_required" };
      record.recoveryAction = "reconcile_dispatcher_lease_before_resuming_work";
    }
    record.recoveryState = resourceState === "critical"
      ? "retired_for_critical_resource_pressure"
      : request.basis === "unsafe_question_policy_blocked"
        ? "retired_after_policy_blocked_question"
          : request.basis === "booting_warm_reviewer_recovery"
            ? "retired_after_booting_warm_reviewer_recovery"
        : request.basis === "missing_live_tmux_session"
          ? "retired_after_missing_live_session"
        : "retired_after_recovery_submit_unanswered";
    if (request.basis === "booting_warm_reviewer_recovery") {
      record.lifecycleState = "retired";
      record.recoveryAction = "retirement_complete";
      record.retirementRequest = null;
    }
  }
  try {
    if (selected.some((request) => request.basis === "booting_warm_reviewer_recovery")) {
      writeWorkerRecordsAtomically(paths, workerRecords, context, "retire_finalize");
    } else {
      writeFileSync(paths.workers, `${JSON.stringify(workerRecords, null, 2)}\n`);
    }
  } catch (error) {
    const failedResult = results.at(-1);
    if (failedResult) failedResult.status = "retired_persistence_recovery_required";
    return packet({ ok: false, status: "blocked", summary: { runId, apply: true, mutation: "partial; exact session retired with durable retiring_physical marker", results }, blockers: [{ code: "worker-retire-finalize-persistence-failed", message: error?.message || "Final retired state could not be persisted after kill.", nextAction: "Reconcile the exact missing session from the durable retiring_physical marker, then finalize the worker record." }] });
  }
  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_retire_apply",
    authorityBasis: workerRetireAuthorityBasis(resourceState, results),
    summary: `${workerRetirePastTenseSummary(resourceState, results.filter(workerRetireResultIsFinal))}.`,
    sourceRefs: results.map((result) => `assignment:${result.assignmentId}`),
    evidenceRefs: results.map((result) => `worker-retire:${result.workerId || result.assignmentId}`),
    recoveryPath: resourceState === "critical" ? "refresh worker status and reconcile recovery-required leases before resuming work" : "warm a replacement manager-owned worker and hand off the next source-owned lane through existing gates",
    recordPolicy: resourceState === "critical" ? "metadata_only_critical_resource_worker_retire" : "metadata_only_worker_retire",
  }, context);
  return packet({
    status: "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-retire-session-and-record",
      resourceState,
      results,
      continuousSelection: buildContinuousSelectionProof({
        code: "continuous-worker-retire",
        mutationClass: "manager_owned_worker_retire",
        runId,
        targets: results,
      }),
      retention: "retire_session_and_summary",
    },
  });
  });
}

function buildBlockedQuestionRetireCandidates({ progressWorkers = [], questionAnswer = null, workersById = new Map(), runOptions = {}, runId = "" } = {}) {
  const blockedQuestions = Array.isArray(questionAnswer?.summary?.blockedQuestions) ? questionAnswer.summary.blockedQuestions : [];
  if (blockedQuestions.length === 0) return [];
  const progressByWorker = new Map((Array.isArray(progressWorkers) ? progressWorkers : [])
    .filter((worker) => worker?.workerId)
    .map((worker) => [worker.workerId, worker]));
  return blockedQuestions
    .filter((question) =>
      question.workerId &&
      question.decision === "block_unsafe_continuation" &&
      question.operatorInterruption === true &&
      Array.isArray(question.reasonCodes) &&
      question.reasonCodes.includes("unsafe_authority_request")
    )
    .filter((question) => !runOptions.workerId || question.workerId === runOptions.workerId)
    .map((question) => {
      const progressWorker = progressByWorker.get(question.workerId) || {};
      const record = workersById.get(question.workerId) || null;
      if (progressWorker.progressState && progressWorker.progressState !== "blocked_question") return null;
      return {
        ...progressWorker,
        workerId: question.workerId,
        sessionName: progressWorker.sessionName || record?.sessionName || "",
        assignmentId: progressWorker.assignmentId || record?.assignmentId || "",
        taskId: progressWorker.taskId || record?.taskId || "",
        progressState: progressWorker.progressState || "blocked_question",
        questionCount: progressWorker.questionCount ?? 1,
        record,
        blockedQuestion: question,
      };
    })
    .filter(Boolean)
    .map((worker) => ({
      ...worker,
      retireBasis: "unsafe_question_policy_blocked",
    }))
    .filter((worker) => worker.record && isManagerOwnedWorker(worker.record, runId) && worker.record.state === "active" && worker.record.sessionName);
}

function workerRetireAuthorityBasis(resourceState = "unknown", results = []) {
  if (resourceState === "critical") return "manager-owned-worker-critical-resource-existing-gates";
  const bases = new Set((Array.isArray(results) ? results : []).map((result) => result.basis).filter(Boolean));
  if (bases.size === 1 && bases.has("unsafe_question_policy_blocked")) {
    return "manager-owned-worker-retire-after-policy-blocked-question-existing-gates";
  }
  if (bases.size === 1 && bases.has("booting_warm_reviewer_recovery")) {
    return "manager-owned-worker-exact-target-booting-reviewer-retire-existing-gates";
  }
  if (bases.size === 1 && bases.has("missing_live_tmux_session")) {
    return "manager-owned-worker-exact-target-missing-session-logical-retire-existing-gates";
  }
  if (bases.has("unsafe_question_policy_blocked")) {
    return "manager-owned-worker-retire-mixed-existing-gates";
  }
  return "manager-owned-worker-retire-after-recovery-existing-gates";
}

function workerRetireSummary(resourceState = "unknown", selected = []) {
  if (resourceState === "critical") return `Terminate ${selected.length} manager-owned worker(s) for critical resource pressure.`;
  const bootingRecoveryCount = selected.filter((request) => request.basis === "booting_warm_reviewer_recovery").length;
  const missingSessionCount = selected.filter((request) => request.basis === "missing_live_tmux_session").length;
  if (missingSessionCount > 0) return `Logically retire ${missingSessionCount} exact-target manager-owned worker record(s) after verified missing live session(s).`;
  if (bootingRecoveryCount > 0) return `Retire ${bootingRecoveryCount} exact-target booting warm reviewer(s) after readiness recovery could not complete.`;
  const blockedQuestionCount = selected.filter((request) => request.basis === "unsafe_question_policy_blocked").length;
  const recoveryCount = selected.length - blockedQuestionCount;
  if (blockedQuestionCount > 0 && recoveryCount > 0) return `Retire ${selected.length} manager-owned worker(s): ${recoveryCount} recovery-stuck and ${blockedQuestionCount} policy-blocked.`;
  if (blockedQuestionCount > 0) return `Retire ${blockedQuestionCount} policy-blocked manager-owned worker(s) after unsafe question classification.`;
  return `Retire ${selected.length} recovery-stuck manager-owned worker(s).`;
}

function workerRetirePastTenseSummary(resourceState = "unknown", results = []) {
  const count = Array.isArray(results) ? results.length : 0;
  if (resourceState === "critical") return `Terminated ${count} manager-owned worker(s) for critical resource pressure`;
  const bootingRecoveryCount = results.filter((result) => result.basis === "booting_warm_reviewer_recovery").length;
  const missingSessionCount = results.filter((result) => result.basis === "missing_live_tmux_session").length;
  if (missingSessionCount > 0) return `Logically retired ${missingSessionCount} exact-target manager-owned worker record(s) after verified missing live session(s)`;
  if (bootingRecoveryCount > 0) return `Retired ${bootingRecoveryCount} exact-target booting warm reviewer(s) after readiness recovery could not complete`;
  const blockedQuestionCount = results.filter((result) => result.basis === "unsafe_question_policy_blocked").length;
  const recoveryCount = count - blockedQuestionCount;
  if (blockedQuestionCount > 0 && recoveryCount > 0) return `Retired ${count} manager-owned worker(s): ${recoveryCount} recovery-stuck and ${blockedQuestionCount} policy-blocked`;
  if (blockedQuestionCount > 0) return `Retired ${blockedQuestionCount} policy-blocked manager-owned worker(s) after unsafe question classification`;
  return `Retired ${count} recovery-stuck manager-owned worker(s)`;
}

function lowercaseFirst(value = "") {
  const text = String(value || "");
  return text ? `${text[0].toLowerCase()}${text.slice(1)}` : "";
}

export function buildWorkerQuestionAnswerPlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  const workerPacket = context.workerStatus || buildWorkerStatus(runOptions, context);
  const workers = Array.isArray(workerPacket.summary?.workers) ? workerPacket.summary.workers.filter(isPlainObject).map(projectWorker) : [];
  const activeWorkers = workers.filter((worker) => worker.state === "active" && isManagerOwnedWorker(worker, runId));
  const questions = Array.isArray(context.questions) ? context.questions : readNdjsonStrict(paths.questions).value;
  const events = Array.isArray(context.events) ? context.events : readNdjsonStrict(paths.events).value;
  const checkpoints = Array.isArray(context.checkpoints) ? context.checkpoints : readJson(paths.checkpoints, []);
  const answeredQuestionIds = answeredQuestionIdSet(events);
  const syntheticQuestions = buildBlockedCheckpointAnswerQuestions(activeWorkers, checkpoints, answeredQuestionIds);
  const evaluatedRequests = [...questions, ...syntheticQuestions]
    .filter(isPlainObject)
    .filter((question) => !answeredQuestionIds.has(normalizeQuestionIdentity(question.questionId || question.id || "")))
    .map((question) => buildWorkerQuestionAnswerRequest(question, activeWorkers, paths, runOptions))
    .filter(Boolean)
    .filter((request) => workerMatchesExactTarget(request, runOptions));
  const blockedQuestions = evaluatedRequests
    .filter((request) => !questionDecisionAllowsAnswer(request.policyDecision))
    .map((request) => compactBlockedQuestionDecision(request.policyDecision));
  const blockedWorkerIds = new Set(blockedQuestions.map((question) => question.workerId).filter(Boolean));
  let candidates = evaluatedRequests.filter((request) => questionDecisionAllowsAnswer(request.policyDecision));
  candidates = candidates.filter((request) => !blockedWorkerIds.has(request.workerId));
  const limit = exactTargetLimit(runOptions, runOptions.limit === null || runOptions.limit === undefined ? candidates.length : Math.max(0, Number(runOptions.limit) || 0));
  const selected = candidates.slice(0, limit);
  if (selected.length === 0) {
    if (blockedQuestions.length > 0) {
      return packet({
        status: "attention",
        summary: {
          runId,
          apply: Boolean(runOptions.apply),
          mutation: "none; unsafe questions blocked before answer transport",
          answerableQuestions: candidates.length,
          planned: 0,
          requests: [],
          blockedQuestions,
          retention: "metadata_only_question_policy",
        },
        blockers: [{
          code: "worker-question-answer-policy-blocked",
          message: `${blockedQuestions.length} worker question(s) require source context or operator authority before a worker can continue.`,
          nextAction: "Review compact blocked question decisions; answer only after source context or operator authority is available.",
        }],
      });
    }
    return packet({
      status: "ready",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", answerableQuestions: candidates.length, planned: 0, requests: [] },
      nextActions: [{ code: "worker-question-answer-not-needed", summary: "No unanswered manager-owned worker question is ready for answer routing.", nextAction: "Continue metadata-only monitoring." }],
    });
  }
  if (!runOptions.apply) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        answerableQuestions: candidates.length,
        planned: selected.length,
        requests: selected,
        blockedQuestions,
        continuousSelection: buildContinuousSelectionProof({
          code: "continuous-worker-answer-question",
          mutationClass: "manager_owned_worker_question_answer",
          runId,
          targets: selected,
        }),
        transport: { primary: "durable_question_answer_file", secondary: "literal_safe_tmux_buffer", pastedText: "read_question_answer_file_path_only" },
      },
      blockers: blockedQuestions.length > 0 ? [{
        code: "worker-question-answer-policy-blocked",
        message: `${blockedQuestions.length} worker question(s) require source context or operator authority before a worker can continue.`,
        nextAction: "Review compact blocked question decisions while allowed source-backed answers proceed.",
      }] : [],
      nextActions: [{ code: "worker-question-answer-apply-ready", summary: `Answer ${selected.length} compact worker question(s).`, nextAction: `node ./scripts/manager-worker-answer-question.mjs --summary-json${workerExactTargetFlags(selected[0]) || ` --limit ${selected.length}`} --apply` }],
    });
  }
  mkdirSync(join(paths.root, "question-answers"), { recursive: true });
  const results = [];
  for (const request of selected) {
    writeFileSync(request.answerPath, renderWorkerQuestionAnswerFile(request));
    writeFileSync(request.pastePath, `${request.pasteText}\n`);
    const paste = pasteWorkerPointer(request, `${request.workerId}-answer`, context);
    results.push({ ...request, status: paste.ok ? "answer_sent" : "failed", paste });
  }
  const failed = results.find((result) => result.status === "failed");
  if (failed) {
    const sent = results.filter((result) => result.status === "answer_sent");
    if (sent.length > 0) {
      ledgerCommand({
        command: "append-event",
        runId,
        stateRoot: runOptions.stateRoot,
        eventType: "worker_question_answer_apply",
        authorityBasis: "manager-owned-worker-question-answer-existing-gates",
        summary: `Partially answered ${sent.length} compact worker question(s) before a later paste failure.`,
        sourceRefs: sent.flatMap((result) => [`question:${result.questionId}`, `assignment:${result.assignmentId}`]),
        evidenceRefs: sent.map((result) => `question-answer:${result.answerPath || result.questionId || result.assignmentId}`),
        recoveryPath: "inspect manager question answer files and tmux paste results before retrying only failed answers",
      }, context);
    }
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "partial", results },
      blockers: [{ code: "worker-question-answer-paste-failed", message: failed.paste?.error || `Failed to paste question answer to ${failed.sessionName}.`, nextAction: "Inspect manager question answer files and tmux paste result before retrying." }],
    });
  }
  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_question_answer_apply",
    authorityBasis: "manager-owned-worker-question-answer-existing-gates",
    summary: `Answered ${results.length} compact worker question(s).`,
    sourceRefs: results.flatMap((result) => [`question:${result.questionId}`, `assignment:${result.assignmentId}`]),
    evidenceRefs: results.map((result) => `question-answer:${result.answerPath || result.questionId || result.assignmentId}`),
    recoveryPath: "rerun manager-worker-progress and inspect compact checkpoints before answering again",
  }, context);
  return packet({
    status: "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-question-answer-file-and-tmux-buffer",
      results,
      blockedQuestions,
      continuousSelection: buildContinuousSelectionProof({
        code: "continuous-worker-answer-question",
        mutationClass: "manager_owned_worker_question_answer",
        runId,
        targets: results,
      }),
      retention: "question_answer_path_and_summary",
    },
    warnings: blockedQuestions.length > 0 ? [{ code: "worker-question-answer-policy-blocked", message: `${blockedQuestions.length} unsafe or source-blocked question(s) were not answered.` }] : [],
  });
}

export function buildWorkerOwnerDelegationPlan(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const runId = safeRunId(runOptions.runId || defaultRunId());
  const paths = managerRunPaths(runId, runOptions, context);
  const progress = context.progressStatus || buildWorkerProgressStatus(runOptions, context);
  const candidates = Array.isArray(progress.summary?.workerProgress)
    ? progress.summary.workerProgress.filter((worker) => worker.assignmentId && worker.laneOwner)
    : [];
  const limit = runOptions.limit === null || runOptions.limit === undefined ? candidates.length : Math.max(0, Number(runOptions.limit) || 0);
  const selected = candidates.slice(0, limit).map((worker) => buildWorkerOwnerDelegationRequest(worker, paths));
  if (selected.length === 0) {
    return packet({
      status: "ready",
      summary: { runId, apply: Boolean(runOptions.apply), mutation: "none", requests: [] },
      nextActions: [{ code: "worker-owner-delegation-not-needed", summary: "No active worker has delegated lane owner evidence.", nextAction: "Continue metadata-only monitoring." }],
    });
  }
  if (!runOptions.apply) {
    return packet({
      status: "ready",
      summary: {
        runId,
        apply: false,
        mutation: "none; dry-run summary only",
        planned: selected.length,
        requests: selected,
        transport: { primary: "durable_owner_delegation_file", secondary: "literal_safe_tmux_buffer", pastedText: "read_owner_delegation_file_path_only" },
      },
      nextActions: [{ code: "worker-owner-delegation-apply-ready", summary: `Send delegated owner guidance to ${selected.length} active worker(s).`, nextAction: `node ./scripts/manager-worker-owner-delegation.mjs --summary-json --limit ${selected.length} --apply` }],
    });
  }
  mkdirSync(join(paths.root, "owner-delegations"), { recursive: true });
  const results = [];
  for (const request of selected) {
    writeFileSync(request.requestPath, renderWorkerOwnerDelegationFile(request));
    writeFileSync(request.pastePath, `${request.pasteText}\n`);
    const paste = pasteWorkerPointer(request, `${request.workerId}-owner`, context);
    results.push({ ...request, status: paste.ok ? "owner_delegation_sent" : "failed", paste });
  }
  const failed = results.find((result) => result.status === "failed");
  if (failed) {
    const sent = results.filter((result) => result.status === "owner_delegation_sent");
    if (sent.length > 0) {
      ledgerCommand({
        command: "append-event",
        runId,
        stateRoot: runOptions.stateRoot,
        eventType: "worker_owner_delegation_apply",
        authorityBasis: "manager-owned-worker-delegated-lane-owner-existing-gates",
        summary: `Partially sent ${sent.length} manager-owned worker owner delegation(s) before a later paste failure.`,
        sourceRefs: sent.flatMap((result) => [`assignment:${result.assignmentId}`, `worker:${result.workerId}`, ...receiptSourceRefs(result)]),
        evidenceRefs: sent.map((result) => `owner-delegation:${result.requestPath || result.workerId || result.assignmentId}`),
        recoveryPath: "inspect manager owner delegation files and tmux paste results before retrying only failed delegations",
      }, context);
    }
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, apply: true, mutation: "partial", results },
      blockers: [{ code: "worker-owner-delegation-paste-failed", message: failed.paste?.error || `Failed to paste owner delegation to ${failed.sessionName}.`, nextAction: "Inspect manager owner delegation files and tmux paste result before retrying." }],
    });
  }
  ledgerCommand({
    command: "append-event",
    runId,
    stateRoot: runOptions.stateRoot,
    eventType: "worker_owner_delegation_apply",
    authorityBasis: "manager-owned-worker-delegated-lane-owner-existing-gates",
    summary: `Sent ${results.length} manager-owned worker owner delegation(s).`,
    sourceRefs: results.flatMap((result) => [`assignment:${result.assignmentId}`, `worker:${result.workerId}`, ...receiptSourceRefs(result)]),
    evidenceRefs: results.map((result) => `owner-delegation:${result.requestPath || result.workerId || result.assignmentId}`),
    recoveryPath: "rerun manager-worker-progress and inspect checkpoints before retrying",
  }, context);
  return packet({
    status: "ready",
    summary: {
      runId,
      apply: true,
      mutation: "manager-owned-worker-owner-delegation-file-and-tmux-buffer",
      results,
      retention: "owner_delegation_path_and_summary",
    },
  });
}

function buildWorkerQuestionAnswerRequest(question = {}, workers = [], paths = {}, options = {}) {
  const questionId = sanitizeLedgerField(question.questionId || question.id || "question", "question", 100);
  const questionSourceRefs = compactSanitizedRefs([
    ...sourceRefList(question.sourceRefs),
    ...sourceRefList(question.sourceRef),
  ]);
  const activeSourceRefs = compactSanitizedRefs([
    ...sourceRefList(options.sourceRefs),
  ]);
  const sourceRefs = compactSanitizedRefs([...questionSourceRefs, ...activeSourceRefs]);
  const assignmentId = assignmentIdFromSourceRefs(sourceRefs);
  const worker = workers.find((candidate) =>
    (question.actor && candidate.workerId === question.actor) ||
    (question.workerId && candidate.workerId === question.workerId) ||
    (assignmentId && candidate.assignmentId === assignmentId),
  );
  if (!worker) return null;
  const policyDecision = buildQuestionDecision({ ...question, sourceRefs }, {
    authorityClass: options.authorityClass,
    assignmentId: worker.assignmentId || assignmentId,
    taskId: worker.taskId || question.taskId,
    runId: options.runId,
    workerId: worker.workerId,
    activeSourceRefs,
    questionSourceRefs,
  });
  const answerPolicyDecision = options.answer ? buildQuestionDecision({
    questionId,
    workerId: worker.workerId,
    type: "implementation",
    summary: options.answer,
    sourceRefs,
    materialDecision: true,
  }, {
    authorityClass: options.authorityClass,
    assignmentId: worker.assignmentId || assignmentId,
    taskId: worker.taskId || question.taskId,
    runId: options.runId,
    workerId: worker.workerId,
    activeSourceRefs,
    questionSourceRefs,
  }) : null;
  const effectivePolicyDecision = answerPolicyDecision || policyDecision;
  const answer = sanitizeLedgerField(options.answer || effectivePolicyDecision.compactAnswer || compactQuestionAnswer(question), "Apply source context and repo policy with best judgment.", 500);
  const safeQuestionId = questionId.replace(/[^a-z0-9_.-]/gi, "-").slice(0, 100);
  const answerPath = join(paths.root, "question-answers", `${worker.workerId}-${safeQuestionId}.md`);
  const pastePath = join(paths.root, "question-answers", `${worker.workerId}-${safeQuestionId}.paste.txt`);
  return {
    questionId,
    workerId: sanitizeLedgerField(worker.workerId || "worker", "worker", 80),
    sessionName: sanitizeLedgerField(worker.sessionName || worker.workerId || "worker", "worker", 80),
    runId: paths.runId,
    stateRoot: paths.proof?.state?.root || "",
    assignmentId: sanitizeLedgerField(assignmentId || worker.assignmentId || "", "", 140),
    taskId: sanitizeLedgerField(worker.taskId || "", "", 140),
    questionType: sanitizeLedgerField(question.questionType || question.type || "worker_question", "worker_question", 80),
    questionSummary: sanitizeLedgerField(question.summary || "worker question", "worker question", 240),
    compactAnswer: answer,
    policyDecision: effectivePolicyDecision,
    decision: effectivePolicyDecision.decision,
    leaseContinuation: effectivePolicyDecision.leaseContinuation,
    recordPolicy: effectivePolicyDecision.recordPolicy,
    reasonCodes: effectivePolicyDecision.reasonCodes,
    sourceRefs,
    answerPath,
    pastePath,
    pasteText: `Please read and follow this manager answer file: ${answerPath}`,
    retention: "question_answer_path_and_summary",
  };
}

function buildBlockedCheckpointAnswerQuestions(workers = [], checkpoints = [], answeredQuestionIds = new Set()) {
  return (Array.isArray(workers) ? workers : [])
    .filter(isPlainObject)
    .flatMap((worker) => {
      const assignmentId = sanitizeLedgerField(worker.assignmentId || "", "", 140);
      if (!assignmentId) return [];
      const latestBlocked = filterWorkerProgressRecords(checkpoints, worker, assignmentId)
        .filter((checkpoint) => classifyWorkerCheckpointBlockerSummary(checkpoint.summary || "").blocked)
        .sort((left, right) => (parseTimeMs(right.timestamp) || 0) - (parseTimeMs(left.timestamp) || 0))[0];
      if (!latestBlocked) return [];
      const checkpointId = sanitizeLedgerField(latestBlocked.checkpointId || latestBlocked.id || "blocked-checkpoint", "blocked-checkpoint", 120);
      const questionId = blockedCheckpointQuestionId(latestBlocked);
      if (answeredQuestionIds.has(normalizeQuestionIdentity(questionId))) return [];
      return [{
        questionId,
        actor: worker.workerId,
        workerId: worker.workerId,
        questionType: "source_context",
        summary: sanitizeLedgerField(latestBlocked.summary || "blocked worker checkpoint needs source context", "blocked worker checkpoint needs source context", 240),
        sourceRefs: [
          `assignment:${assignmentId}`,
          `task:${worker.taskId || ""}`,
          `checkpoint:${checkpointId}`,
        ].filter((ref) => !ref.endsWith(":")),
      }];
    });
}

function blockedCheckpointQuestionId(checkpoint = {}) {
  const checkpointId = sanitizeLedgerField(checkpoint.checkpointId || checkpoint.id || "blocked-checkpoint", "blocked-checkpoint", 120);
  return `checkpoint-blocker-${checkpointId}`.replace(/[^a-z0-9_.-]/gi, "-").slice(0, 100);
}

function assignmentIdFromSourceRefs(sourceRefs = []) {
  const assignmentRef = sourceRefs.find((ref) => /^assignment:/.test(String(ref || "")));
  if (assignmentRef) return String(assignmentRef).replace(/^assignment:/, "");
  return "";
}

function answeredQuestionIdSet(events = []) {
  return new Set(
    (Array.isArray(events) ? events : [])
      .filter((event) => event?.eventType === "worker_question_answer_apply")
      .flatMap((event) => sourceRefList(event.sourceRefs || []))
      .map((ref) => String(ref || ""))
      .filter((ref) => ref.startsWith("question:"))
      .map((ref) => normalizeQuestionIdentity(ref))
      .filter(Boolean),
  );
}

function normalizeQuestionIdentity(value) {
  return sanitizeLedgerField(String(value || "").replace(/^question:/, ""), "", 100)
    .toLowerCase()
    .replace(/[^a-z0-9_.-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 100);
}

function renderWorkerQuestionAnswerFile(request = {}) {
  return [
    "# Manager Worker Question Answer",
    "",
    `runId: ${request.runId}`,
    `workerId: ${request.workerId}`,
    `assignmentId: ${request.assignmentId}`,
    `taskId: ${request.taskId}`,
    `questionId: ${request.questionId}`,
    `questionType: ${request.questionType}`,
    `retention: ${request.retention}`,
    "",
    "## Question Summary",
    "",
    request.questionSummary,
    "",
    "## Answer",
    "",
    request.compactAnswer,
    "",
    "## Source References",
    "",
    ...(request.sourceRefs.length > 0 ? request.sourceRefs.map((ref) => `- ${ref}`) : ["- none"]),
    "",
    "## Resume",
    "",
    "Continue the assigned lane using the answer above. Record a compact checkpoint or a new material question through the manager ledger; do not inspect or retain raw provider output.",
    "",
  ].join("\n");
}

